uccessMessage":"Correct - relate the answer to the booked aircraft and the conditions on the day."}],"commonSources":[["NZ CAA Flight Instructor Guide briefing framework","https://www.aviation.govt.nz/licensing-and-certification/pilots/flight-training/flight-instructor-guide/briefings-introduction/"],["RAAus RPC syllabus","https://raaus.com.au/wp-content/uploads/2023/10/1-syllabus-of-flight-training-issue-7-v2-single-pages-1.pdf"],["RAAus Flight Operations Manual","https://raaus.com.au/wp-content/uploads/2024/07/RAAus-Flight-Operations-Manual.pdf"],["Tecnam P92 family overview - general information only","https://tecnam.com/aircraft/p92-echo-mkii/"]]},{"code":"1.01-4","title":"Straight and Level","sources":[["CAA straight and level","https://www.aviation.govt.nz/licensing-and-certification/pilots/flight-training/flight-instructor-guide/straight-and-level/"]],"outcomes":["Set and maintain straight-and-level flight using attitude, power and trim.","Recognise and correct small altitude, heading and airspeed trends.","Use a disciplined outside scan with short instrument cross-checks."],"p92":["Use the P92 cowling-to-horizon picture and wing symmetry as primary attitude references.","Select a suitable power setting from the aircraft checklist and confirm the resulting performance rather than forcing a memorised number.","Trim only after the desired attitude, power and balance are stable.","Apply small corrections, pause, assess the trend, and remove the correction."],"sequence":["Lookout, select a distant heading reference and set the normal attitude.","Set power, allow airspeed to stabilise, then trim.","Scan outside for attitude and traffic; cross-check altitude, heading, airspeed and engine indications.","Correct one developing trend with a small coordinated input.","Re-establish straight and level after a climb, descent and turn."],"threats":["Instrument chasing: fly the outside attitude and use instruments to confirm the trend.","Poor seating position: set the seat and sight picture before engine start.","Unnoticed drift or traffic: keep the scan moving through the full field of view."],"readiness":["I can describe attitude-power-trim in the correct order.","I know the difference between a trend and a momentary instrument movement.","I can identify the P92 outside references I will use."],"questions":[{"prompt":"What is the best order for establishing straight-and-level flight?","correct":"Attitude, power, balance, then trim.","distractors":["Trim, power, attitude, then lookout.","Power, trim, then choose any attitude.","Instrument scan, flap, then attitude."]},{"prompt":"How should a small altitude trend normally be corrected?","correct":"Make a small attitude correction, pause and reassess.","distractors":["Make a large correction and hold it until the altimeter reverses.","Use trim as the primary elevator control.","Look only at the altimeter."]},{"prompt":"Where should most visual attention be in normal VFR straight-and-level flight?","correct":"Outside, with brief instrument cross-checks.","distractors":["On the altimeter continuously.","On the airspeed indicator continuously.","On the engine instruments continuously."]}],"programIndex":2,"name":"RPC 02 - Straight and Level","quiz":[{"id":"1014-q1","type":"single_choice","prompt":"What is the best order for establishing straight-and-level flight?","options":[{"id":"1014-q1-o1","label":"Power, trim, then choose any attitude."},{"id":"1014-q1-o2","label":"Instrument scan, flap, then attitude."},{"id":"1014-q1-o3","label":"Attitude, power, balance, then trim."},{"id":"1014-q1-o4","label":"Trim, power, attitude, then lookout."}],"correctAnswer":"1014-q1-o3","required":true,"incorrectExplanation":"Review the lesson briefing, the current aircraft documents and the instructor-approved sequence before trying again.","successMessage":"Correct - relate the answer to the booked aircraft and the conditions on the day."},{"id":"1014-q2","type":"single_choice","prompt":"How should a small altitude trend normally be corrected?","options":[{"id":"1014-q2-o1","label":"Look only at the altimeter."},{"id":"1014-q2-o2","label":"Make a small attitude correction, pause and reassess."},{"id":"1014-q2-o3","label":"Make a large correction and hold it until the altimeter reverses."},{"id":"1014-q2-o4","label":"Use trim as the primary elevator control."}],"correctAnswer":"1014-q2-o2","required":true,"incorrectExplanation":"Review the lesson briefing, the current aircraft documents and the instructor-approved sequence before trying again.","successMessage":"Correct - relate the answer to the booked aircraft and the conditions on the day."},{"id":"1014-q3","type":"single_choice","prompt":"Where should most visual attention be in normal VFR straight-and-level flight?","options":[{"id":"1014-q3-o1","label":"Outside, with brief instrument cross-checks."},{"id":"1014-q3-o2","label":"On the altimeter continuously."},{"id":"1014-q3-o3","label":"On the airspeed indicator continuously."},{"id":"1014-q3-o4","label":"On the engine instruments continuously."}],"correctAnswer":"1014-q3-o1","required":true,"incorrectExplanation":"Review the lesson briefing, the current aircraft documents and the instructor-approved sequence before trying again.","successMessage":"Correct - relate the answer to the booked aircraft and the conditions on the day."},{"id":"1014-q4","type":"single_choice","prompt":"Before using a P92 speed, RPM, flap setting, limitation or emergency action, which source controls?","options":[{"id":"1014-q4-o1","label":"A figure remembered from another aircraft."},{"id":"1014-q4-o2","label":"An online forum post."},{"id":"1014-q4-o3","label":"The current Tecnam marketing page."},{"id":"1014-q4-o4","label":"The current flight manual, cockpit placard/checklist and instructor brief for the booked aircraft."}],"correctAnswer":"1014-q4-o4","required":true,"incorrectExplanation":"Review the lesson briefing, the current aircraft documents and the instructor-approved sequence before trying again.","successMessage":"Correct - relate the answer to the booked aircraft and the conditions on the day."}],"commonSources":[["NZ CAA Flight Instructor Guide briefing framework","https://www.aviation.govt.nz/licensing-and-certification/pilots/flight-training/flight-instructor-guide/briefings-introduction/"],["RAAus RPC syllabus","https://raaus.com.au/wp-content/uploads/2023/10/1-syllabus-of-flight-training-issue-7-v2-single-pages-1.pdf"],["RAAus Flight Operations Manual","https://raaus.com.au/wp-content/uploads/2024/07/RAAus-Flight-Operations-Manual.pdf"],["Tecnam P92 family overview - general information only","https://tecnam.com/aircraft/p92-echo-mkii/"]]},{"code":"1.01-5","title":"Climbing and Descending","sources":[["CAA climbing and descending","https://www.aviation.govt.nz/licensing-and-certification/pilots/flight-training/flight-instructor-guide/climbing-and-descending/"]],"outcomes":["Enter, maintain and leave normal climbs and descents using a repeatable sequence.","Manage lookout, balance, engine indications and configuration throughout.","Anticipate level-off and stabilise without large altitude or airspeed excursions."],"p92":["Confirm the booked P92’s climb, glide and configuration figures from its current checklist.","Use attitude for the nominated airspeed, power appropriate to the phase, rudder for balance, then trim.","Monitor the Rotax engine indications and comply with any temperature-management guidance in the aircraft checklist.","Treat carburettor-heat use, if fitted, as aircraft-specific and follow the installed-aircraft checklist."],"sequence":["Clear the area above, ahead and around the aircraft.","Enter the climb with attitude and power in the aircraft-specific order; balance and trim.","Maintain reference, airspeed and engine scan; clear the blind area as instructed.","Lead the level-off, accelerate, set cruise power and trim.","Enter a powered descent and a glide, then lead each level-off."],"threats":["Reduced forward visibility in climb: use the instructor-approved clearing technique.","Airspeed decay after level-off: allow acceleration before selecting final cruise power.","Engine mishandling: use the checklist sequence and monitor limitations."],"readiness":["I can state the entry and level-off sequence for a climb and descent.","I know where the booked aircraft’s climb and glide figures are found.","I can explain why lookout changes during pitch changes."],"questions":[{"prompt":"What should be confirmed before raising the nose into a climb?","correct":"The flight path and surrounding airspace are clear.","distractors":["The trim is fully nose-up.","The flaps are extended regardless of procedure.","The altimeter is ignored."]},{"prompt":"Why is level-off started before reaching the nominated altitude?","correct":"The aircraft needs time and distance to change flight path and accelerate.","distractors":["The altimeter always reads high.","The engine must be stopped from climbing.","It prevents the need to trim."]},{"prompt":"During a glide, what primarily controls airspeed?","correct":"Attitude.","distractors":["Trim alone.","Rudder position.","Radio volume."]}],"programIndex":3,"name":"RPC 03 - Climbing and Descending","quiz":[{"id":"1015-q1","type":"single_choice","prompt":"What should be confirmed before raising the nose into a climb?","options":[{"id":"1015-q1-o1","label":"The flaps are extended regardless of procedure."},{"id":"1015-q1-o2","label":"The altimeter is ignored."},{"id":"1015-q1-o3","label":"The flight path and surrounding airspace are clear."},{"id":"1015-q1-o4","label":"The trim is fully nose-up."}],"correctAnswer":"1015-q1-o3","required":true,"incorrectExplanation":"Review the lesson briefing, the current aircraft documents and the instructor-approved sequence before trying again.","successMessage":"Correct - relate the answer to the booked aircraft and the conditions on the day."},{"id":"1015-q2","type":"single_choice","prompt":"Why is level-off started before reaching the nominated altitude?","options":[{"id":"1015-q2-o1","label":"It prevents the need to trim."},{"id":"1015-q2-o2","label":"The aircraft needs time and distance to change flight path and accelerate."},{"id":"1015-q2-o3","label":"The altimeter always reads high."},{"id":"1015-q2-o4","label":"The engine must be stopped from climbing."}],"correctAnswer":"1015-q2-o2","required":true,"incorrectExplanation":"Review the lesson briefing, the current aircraft documents and the instructor-approved sequence before trying again.","successMessage":"Correct - relate the answer to the booked aircraft and the conditions on the day."},{"id":"1015-q3","type":"single_choice","prompt":"During a glide, what primarily controls airspeed?","options":[{"id":"1015-q3-o1","label":"Attitude."},{"id":"1015-q3-o2","label":"Trim alone."},{"id":"1015-q3-o3","label":"Rudder position."},{"id":"1015-q3-o4","label":"Radio volume."}],"correctAnswer":"1015-q3-o1","required":true,"incorrectExplanation":"Review the lesson briefing, the current aircraft documents and the instructor-approved sequence before trying again.","successMessage":"Correct - relate the answer to the booked aircraft and the conditions on the day."},{"id":"1015-q4","type":"single_choice","prompt":"Before using a P92 speed, RPM, flap setting, limitation or emergency action, which source controls?","options":[{"id":"1015-q4-o1","label":"A figure remembered from another aircraft."},{"id":"1015-q4-o2","label":"An online forum post."},{"id":"1015-q4-o3","label":"The current Tecnam marketing page."},{"id":"1015-q4-o4","label":"The current flight manual, cockpit placard/checklist and instructor brief for the booked aircraft."}],"correctAnswer":"1015-q4-o4","required":true,"incorrectExplanation":"Review the lesson briefing, the current aircraft documents and the instructor-approved sequence before trying again.","successMessage":"Correct - relate the answer to the booked aircraft and the conditions on the day."}],"commonSources":[["NZ CAA Flight Instructor Guide briefing framework","https://www.aviation.govt.nz/licensing-and-certification/pilots/flight-training/flight-instructor-guide/briefings-introduction/"],["RAAus RPC syllabus","https://raaus.com.au/wp-content/uploads/2023/10/1-syllabus-of-flight-training-issue-7-v2-single-pages-1.pdf"],["RAAus Flight Operations Manual","https://raaus.com.au/wp-content/uploads/2024/07/RAAus-Flight-Operations-Manual.pdf"],["Tecnam P92 family overview - general information only","https://tecnam.com/aircraft/p92-echo-mkii/"]]},{"code":"1.01-6","title":"Medium, Climbing and Descending Turns","sources":[["CAA medium, climbing and descending turns","https://www.aviation.govt.nz/licensing-and-certification/pilots/flight-training/flight-instructor-guide/medium-climbing-and-descending-turns/"]],"outcomes":["Enter, maintain and exit coordinated level turns up to the lesson bank limit.","Adapt the turn for climbing and descending performance.","Apply lookout, balance and roll-out anticipation consistently."],"p92":["Use the P92 wing and horizon picture to judge bank while cross-checking balance and altitude.","Coordinate aileron and rudder during roll, then centralise them as the required bank is reached.","Use the appropriate attitude and power for climbing or descending turns; do not attempt to hold level-flight performance.","Anticipate roll-out using an outside reference and remove back pressure as the wings level."],"sequence":["Complete lookout in the intended direction and clear the turn.","Roll with coordinated aileron and rudder; set bank and adjust back pressure.","Maintain bank, balance, altitude or nominated climb/descent performance.","Look through the turn and identify traffic and the roll-out reference.","Lead the roll-out with coordinated controls and re-establish the required flight condition."],"threats":["Looking only into the turn: scan across, above and below the flight path.","Overbanking or altitude loss: recognise the trend early and correct smoothly.","Skid or slip: use the balance indication as confirmation, not as a substitute for feel and outside references."],"readiness":["I can explain why back pressure normally increases as bank is established.","I know how a climbing turn’s performance differs from a level turn.","I can describe a complete lookout before and during the turn."],"questions":[{"prompt":"What control combination should initiate a normal turn?","correct":"Coordinated aileron and rudder in the direction of turn.","distractors":["Rudder alone.","Elevator alone.","Opposite aileron and rudder."]},{"prompt":"What tendency normally appears if bank increases without enough lift being redirected upward?","correct":"Altitude decreases.","distractors":["Airspeed becomes zero.","The aircraft climbs automatically.","The engine stops."]},{"prompt":"When should the pilot begin looking toward the roll-out reference?","correct":"Before reaching the required heading.","distractors":["Only after the wings are level.","After closing the throttle.","Only when the instructor calls the heading."]}],"programIndex":4,"name":"RPC 04 - Medium, Climbing and Descending Turns","quiz":[{"id":"1016-q1","type":"single_choice","prompt":"What control combination should initiate a normal turn?","options":[{"id":"1016-q1-o1","label":"Elevator alone."},{"id":"1016-q1-o2","label":"Opposite aileron and rudder."},{"id":"1016-q1-o3","label":"Coordinated aileron and rudder in the direction of turn."},{"id":"1016-q1-o4","label":"Rudder alone."}],"correctAnswer":"1016-q1-o3","required":true,"incorrectExplanation":"Review the lesson briefing, the current aircraft documents and the instructor-approved sequence before trying again.","successMessage":"Correct - relate the answer to the booked aircraft and the conditions on the day."},{"id":"1016-q2","type":"single_choice","prompt":"What tendency normally appears if bank increases without enough lift being redirected upward?","options":[{"id":"1016-q2-o1","label":"The engine stops."},{"id":"1016-q2-o2","label":"Altitude decreases."},{"id":"1016-q2-o3","label":"Airspeed becomes zero."},{"id":"1016-q2-o4","label":"The aircraft climbs automatically."}],"correctAnswer":"1016-q2-o2","required":true,"incorrectExplanation":"Review the lesson briefing, the current aircraft documents and the instructor-approved sequence before trying again.","successMessage":"Correct - relate the answer to the booked aircraft and the conditions on the day."},{"id":"1016-q3","type":"single_choice","prompt":"When should the pilot begin looking toward the roll-out reference?","options":[{"id":"1016-q3-o1","label":"Before reaching the required heading."},{"id":"1016-q3-o2","label":"Only after the wings are level."},{"id":"1016-q3-o3","label":"After closing the throttle."},{"id":"1016-q3-o4","label":"Only when the instructor calls the heading."}],"correctAnswer":"1016-q3-o1","required":true,"incorrectExplanation":"Review the lesson briefing, the current aircraft documents and the instructor-approved sequence before trying again.","successMessage":"Correct - relate the answer to the booked aircraft and the conditions on the day."},{"id":"1016-q4","type":"single_choice","prompt":"Before using a P92 speed, RPM, flap setting, limitation or emergency action, which source controls?","options":[{"id":"1016-q4-o1","label":"A figure remembered from another aircraft."},{"id":"1016-q4-o2","label":"An online forum post."},{"id":"1016-q4-o3","label":"The current Tecnam marketing page."},{"id":"1016-q4-o4","label":"The current flight manual, cockpit placard/checklist and instructor brief for the booked aircraft."}],"correctAnswer":"1016-q4-o4","required":true,"incorrectExplanation":"Review the lesson briefing, the current aircraft documents and the instructor-approved sequence before trying again.","successMessage":"Correct - relate the answer to the booked aircraft and the conditions on the day."}],"commonSources":[["NZ CAA Flight Instructor Guide briefing framework","https://www.aviation.govt.nz/licensing-and-certification/pilots/flight-training/flight-instructor-guide/briefings-introduction/"],["RAAus RPC syllabus","https://raaus.com.au/wp-content/uploads/2023/10/1-syllabus-of-flight-training-issue-7-v2-single-pages-1.pdf"],["RAAus Flight Operations Manual","https://raaus.com.au/wp-content/uploads/2024/07/RAAus-Flight-Operations-Manual.pdf"],["Tecnam P92 family overview - general information only","https://tecnam.com/aircraft/p92-echo-mkii/"]]},{"code":"1.01-7","title":"Slow Flight and Basic Stalls","sources":[["CAA slow flight","https://www.aviation.govt.nz/licensing-and-certification/pilots/flight-training/flight-instructor-guide/slow-flight/"],["CAA basic stalling","https://www.aviation.govt.nz/licensing-and-certification/pilots/flight-training/flight-instructor-guide/basic-stalling/"]],"outcomes":["Recognise the changing control response and handling cues as speed reduces.","Identify an approaching stall and recover promptly using the approved sequence.","Maintain height discipline, lookout and configuration awareness."],"p92":["Use only P92 configurations, speeds and minimum heights authorised by the CFI and the booked aircraft’s flight manual.","Expect reduced control effectiveness, increased adverse yaw and the need for disciplined balance at low speed.","Recover by reducing angle of attack first, applying power as authorised, controlling yaw and returning to the required flight path.","Do not practise spins; discontinue any exercise that does not develop as briefed."],"sequence":["HASELL-style safety checks and clearing turns as directed by the instructor.","Reduce power, maintain height and configure while observing attitude and control feel.","Maintain slow flight straight and in shallow turns with coordinated inputs.","Approach the stall, identify cues, then recover at the nominated cue.","Re-establish a safe flight path, complete after-take-off style checks as applicable, and review height loss."],"threats":["Excess rudder or crossed controls: keep balance and use coordinated recovery inputs.","Fixation on airspeed: recognise attitude, buffet, sound and control feel as a combined picture.","Secondary stall: avoid an abrupt pull-up during flight-path recovery."],"readiness":["I can explain that a stall is caused by critical angle of attack, not a particular airspeed.","I can state why angle-of-attack reduction is the first recovery requirement.","I know the exercise will stop if height, configuration or aircraft behaviour is outside the brief."],"questions":[{"prompt":"What causes an aerodynamic stall?","correct":"The wing exceeds its critical angle of attack.","distractors":["The airspeed indicator reaches one fixed number in every condition.","Engine RPM falls below cruise.","The flaps are selected."]},{"prompt":"What is the first aerodynamic requirement in stall recovery?","correct":"Reduce the angle of attack.","distractors":["Raise the nose.","Apply full rudder.","Retrim before moving the controls."]},{"prompt":"Why must yaw be controlled near the stall?","correct":"Yaw can promote wing drop and an incipient spin.","distractors":["Yaw always increases lift equally on both wings.","Yaw prevents any loss of height.","Yaw retracts the flaps."]}],"programIndex":5,"name":"RPC 05 - Slow Flight and Basic Stalls","quiz":[{"id":"1017-q1","type":"single_choice","prompt":"What causes an aerodynamic stall?","options":[{"id":"1017-q1-o1","label":"Engine RPM falls below cruise."},{"id":"1017-q1-o2","label":"The flaps are selected."},{"id":"1017-q1-o3","label":"The wing exceeds its critical angle of attack."},{"id":"1017-q1-o4","label":"The airspeed indicator reaches one fixed number in every condition."}],"correctAnswer":"1017-q1-o3","required":true,"incorrectExplanation":"Review the lesson briefing, the current aircraft documents and the instructor-approved sequence before trying again.","successMessage":"Correct - relate the answer to the booked aircraft and the conditions on the day."},{"id":"1017-q2","type":"single_choice","prompt":"What is the first aerodynamic requirement in stall recovery?","options":[{"id":"1017-q2-o1","label":"Retrim before moving the controls."},{"id":"1017-q2-o2","label":"Reduce the angle of attack."},{"id":"1017-q2-o3","label":"Raise the nose."},{"id":"1017-q2-o4","label":"Apply full rudder."}],"correctAnswer":"1017-q2-o2","required":true,"incorrectExplanation":"Review the lesson briefing, the current aircraft documents and the instructor-approved sequence before trying again.","successMessage":"Correct - relate the answer to the booked aircraft and the conditions on the day."},{"id":"1017-q3","type":"single_choice","prompt":"Why must yaw be controlled near the stall?","options":[{"id":"1017-q3-o1","label":"Yaw can promote wing drop and an incipient spin."},{"id":"1017-q3-o2","label":"Yaw always increases lift equally on both wings."},{"id":"1017-q3-o3","label":"Yaw prevents any loss of height."},{"id":"1017-q3-o4","label":"Yaw retracts the flaps."}],"correctAnswer":"1017-q3-o1","required":true,"incorrectExplanation":"Review the lesson briefing, the current aircraft documents and the instructor-approved sequence before trying again.","successMessage":"Correct - relate the answer to the booked aircraft and the conditions on the day."},{"id":"1017-q4","type":"single_choice","prompt":"Before using a P92 speed, RPM, flap setting, limitation or emergency action, which source controls?","options":[{"id":"1017-q4-o1","label":"A figure remembered from another aircraft."},{"id":"1017-q4-o2","label":"An online forum post."},{"id":"1017-q4-o3","label":"The current Tecnam marketing page."},{"id":"1017-q4-o4","label":"The current flight manual, cockpit placard/checklist and instructor brief for the booked aircraft."}],"correctAnswer":"1017-q4-o4","required":true,"incorrectExplanation":"Review the lesson briefing, the current aircraft documents and the instructor-approved sequence before trying again.","successMessage":"Correct - relate the answer to the booked aircraft and the conditions on the day."}],"commonSources":[["NZ CAA Flight Instructor Guide briefing framework","https://www.aviation.govt.nz/licensing-and-certification/pilots/flight-training/flight-instructor-guide/briefings-introduction/"],["RAAus RPC syllabus","https://raaus.com.au/wp-content/uploads/2023/10/1-syllabus-of-flight-training-issue-7-v2-single-pages-1.pdf"],["RAAus Flight Operations Manual","https://raaus.com.au/wp-content/uploads/2024/07/RAAus-Flight-Operations-Manual.pdf"],["Tecnam P92 family overview - general information only","https://tecnam.com/aircraft/p92-echo-mkii/"]]},{"code":"1.01-8.1/8.3","title":"Circuit - Introduction","sources":[["CAA circuit introduction","https://www.aviation.govt.nz/licensing-and-certification/pilots/flight-training/flight-instructor-guide/circuit-introduction/"],["CAA circuit considerations","https://www.aviation.govt.nz/licensing-and-certification/pilots/flight-training/flight-instructor-guide/circuit-considerations/"]],"outcomes":["Fly the normal circuit sequence with correct spacing, checks and radio awareness.","Conduct a normal take-off, stabilised approach and landing under instruction.","Recognise early when a go-around is the safer outcome."],"p92":["Use the booked P92 checklist for take-off power, flap, climb and approach configurations.","Account for the high-wing sight picture when judging runway position, circuit spacing and flare attitude.","Use coordinated rudder during take-off and climb, particularly as power and airspeed change.","Protect the nosewheel after touchdown and maintain directional control while decelerating."],"sequence":["Confirm runway, wind, traffic, take-off brief and abort plan.","Line up, set power, verify indications, maintain centreline and rotate as briefed.","Track upwind, crosswind and downwind with lookout, calls and checks.","Select base and final using picture, wind and energy; confirm a stabilised approach.","Flare, land, maintain directional control, or go around without delay if criteria are not met."],"threats":["Task saturation: use standard circuit gates and verbalise the next priority.","Unstable approach: go around early; do not try to rescue the landing.","Traffic conflict: listen, look, communicate and adjust spacing while maintaining aircraft control."],"readiness":["I can draw and brief the local circuit including standard calls.","I know the instructor’s stabilised-approach and go-around gates.","I can find the P92 take-off and approach configuration in the cockpit checklist."],"questions":[{"prompt":"What is the best response to an approach outside the agreed stabilised criteria?","correct":"Go around promptly.","distractors":["Continue because every approach can be recovered.","Use large control inputs near the ground.","Turn off the radio."]},{"prompt":"What should be checked immediately after take-off power is applied?","correct":"Expected engine indications and acceleration while maintaining centreline.","distractors":["Only the altimeter.","The landing light switch position only.","The passenger’s phone."]},{"prompt":"Why is circuit spacing adjusted for wind?","correct":"Wind changes groundspeed and the aircraft’s position relative to the runway.","distractors":["Wind changes the runway length.","Wind removes the need for lookout.","Wind makes radio calls optional."]}],"programIndex":6,"name":"RPC 06 - Circuit - Introduction","quiz":[{"id":"1018183-q1","type":"single_choice","prompt":"What is the best response to an approach outside the agreed stabilised criteria?","options":[{"id":"1018183-q1-o1","label":"Go around promptly."},{"id":"1018183-q1-o2","label":"Continue because every approach can be recovered."},{"id":"1018183-q1-o3","label":"Use large control inputs near the ground."},{"id":"1018183-q1-o4","label":"Turn off the radio."}],"correctAnswer":"1018183-q1-o1","required":true,"incorrectExplanation":"Review the lesson briefing, the current aircraft documents and the instructor-approved sequence before trying again.","successMessage":"Correct - relate the answer to the booked aircraft and the conditions on the day."},{"id":"1018183-q2","type":"single_choice","prompt":"What should be checked immediately after take-off power is applied?","options":[{"id":"1018183-q2-o1","label":"Only the altimeter."},{"id":"1018183-q2-o2","label":"The landing light switch position only."},{"id":"1018183-q2-o3","label":"The passenger’s phone."},{"id":"1018183-q2-o4","label":"Expected engine indications and acceleration while maintaining centreline."}],"correctAnswer":"1018183-q2-o4","required":true,"incorrectExplanation":"Review the lesson briefing, the current aircraft documents and the instructor-approved sequence before trying again.","successMessage":"Correct - relate the answer to the booked aircraft and the conditions on the day."},{"id":"1018183-q3","type":"single_choice","prompt":"Why is circuit spacing adjusted for wind?","options":[{"id":"1018183-q3-o1","label":"Wind removes the need for lookout."},{"id":"1018183-q3-o2","label":"Wind makes radio calls optional."},{"id":"1018183-q3-o3","label":"Wind changes groundspeed and the aircraft’s position relative to the runway."},{"id":"1018183-q3-o4","label":"Wind changes the runway length."}],"correctAnswer":"1018183-q3-o3","required":true,"incorrectExplanation":"Review the lesson briefing, the current aircraft documents and the instructor-approved sequence before trying again.","successMessage":"Correct - relate the answer to the booked aircraft and the conditions on the day."},{"id":"1018183-q4","type":"single_choice","prompt":"Before using a P92 speed, RPM, flap setting, limitation or emergency action, which source controls?","options":[{"id":"1018183-q4-o1","label":"The current Tecnam marketing page."},{"id":"1018183-q4-o2","label":"The current flight manual, cockpit placard/checklist and instructor brief for the booked aircraft."},{"id":"1018183-q4-o3","label":"A figure remembered from another aircraft."},{"id":"1018183-q4-o4","label":"An online forum post."}],"correctAnswer":"1018183-q4-o2","required":true,"incorrectExplanation":"Review the lesson briefing, the current aircraft documents and the instructor-approved sequence before trying again.","successMessage":"Correct - relate the answer to the booked aircraft and the conditions on the day."}],"commonSources":[["NZ CAA Flight Instructor Guide briefing framework","https://www.aviation.govt.nz/licensing-and-certification/pilots/flight-training/flight-instructor-guide/briefings-introduction/"],["RAAus RPC syllabus","https://raaus.com.au/wp-content/uploads/2023/10/1-syllabus-of-flight-training-issue-7-v2-single-pages-1.pdf"],["RAAus Flight Operations Manual","https://raaus.com.au/wp-content/uploads/2024/07/RAAus-Flight-Operations-Manual.pdf"],["Tecnam P92 family overview - general information only","https://tecnam.com/aircraft/p92-echo-mkii/"]]},{"code":"1.01-8.6","title":"Circuits - Flapless and Missed Approaches","sources":[["CAA flapless landings","https://www.aviation.govt.nz/licensing-and-certification/pilots/flight-training/flight-instructor-guide/flapless-landings/"],["CAA circuit considerations","https://www.aviation.govt.nz/licensing-and-certification/pilots/flight-training/flight-instructor-guide/circuit-considerations/"]],"outcomes":["Plan and fly a flapless circuit using the changed attitude, speed and spacing.","Initiate a go-around from approach or landing without hesitation.","Manage P92 power, flap and trim changes without losing directional control."],"p92":["Expect a different P92 nose attitude, approach speed and landing distance when flap is unavailable; use the aircraft checklist values.","For a go-around, prioritise power, attitude, balance and flight path before configuration changes.","Retract electric flap in approved stages while confirming the indication and maintaining the nominated speed.","Anticipate trim-force changes; hold attitude with the flight controls and retrim only when stable."],"sequence":["Brief the flapless pattern, runway requirement, wind and go-around plan.","Adjust circuit spacing and configure for the approved flapless approach.","Confirm stabilisation at the agreed gate and continue or go around.","Practise a go-around: power, attitude, balance, configuration, track and communicate.","Rejoin the circuit, identify the cause and avoid repeating an unstable setup."],"threats":["Premature flap retraction: configuration must not compromise climb performance or control.","Pitch change with power: hold the required attitude and coordinate rudder.","Plan-continuation bias: a go-around is a normal manoeuvre, not a failed landing."],"readiness":["I can explain how flapless spacing and landing distance differ.","I know the P92 go-around priorities and where its configuration limits are found.","I will call and execute a go-around when any agreed gate is missed."],"questions":[{"prompt":"What is the first priority when initiating a go-around?","correct":"Establish power, attitude and control for a safe flight path.","distractors":["Retract all flap immediately.","Make the radio call before flying the aircraft.","Retrim before changing power."]},{"prompt":"Compared with a normal flap approach, a flapless approach generally requires what?","correct":"Different attitude, speed, spacing and landing-distance planning.","distractors":["No change to planning or performance.","A steeper flare with the engine stopped.","No wind correction."]},{"prompt":"When should flap be changed during a go-around?","correct":"In the approved sequence while flight path and speed remain controlled.","distractors":["All at once before power is applied.","Only after leaving the circuit.","Whenever the trim force becomes noticeable."]}],"programIndex":7,"name":"RPC 07 - Circuits - Flapless and Missed Approaches","quiz":[{"id":"10186-q1","type":"single_choice","prompt":"What is the first priority when initiating a go-around?","options":[{"id":"10186-q1-o1","label":"Establish power, attitude and control for a safe flight path."},{"id":"10186-q1-o2","label":"Retract all flap immediately."},{"id":"10186-q1-o3","label":"Make the radio call before flying the aircraft."},{"id":"10186-q1-o4","label":"Retrim before changing power."}],"correctAnswer":"10186-q1-o1","required":true,"incorrectExplanation":"Review the lesson briefing, the current aircraft documents and the instructor-approved sequence before trying again.","successMessage":"Correct - relate the answer to the booked aircraft and the conditions on the day."},{"id":"10186-q2","type":"single_choice","prompt":"Compared with a normal flap approach, a flapless approach generally requires what?","options":[{"id":"10186-q2-o1","label":"No change to planning or performance."},{"id":"10186-q2-o2","label":"A steeper flare with the engine stopped."},{"id":"10186-q2-o3","label":"No wind correction."},{"id":"10186-q2-o4","label":"Different attitude, speed, spacing and landing-distance planning."}],"correctAnswer":"10186-q2-o4","required":true,"incorrectExplanation":"Review the lesson briefing, the current aircraft documents and the instructor-approved sequence before trying again.","successMessage":"Correct - relate the answer to the booked aircraft and the conditions on the day."},{"id":"10186-q3","type":"single_choice","prompt":"When should flap be changed during a go-around?","options":[{"id":"10186-q3-o1","label":"Only after leaving the circuit."},{"id":"10186-q3-o2","label":"Whenever the trim force becomes noticeable."},{"id":"10186-q3-o3","label":"In the approved sequence while flight path and speed remain controlled."},{"id":"10186-q3-o4","label":"All at once before power is applied."}],"correctAnswer":"10186-q3-o3","required":true,"incorrectExplanation":"Review the lesson briefing, the current aircraft documents and the instructor-approved sequence before trying again.","successMessage":"Correct - relate the answer to the booked aircraft and the conditions on the day."},{"id":"10186-q4","type":"single_choice","prompt":"Before using a P92 speed, RPM, flap setting, limitation or emergency action, which source controls?","options":[{"id":"10186-q4-o1","label":"The current Tecnam marketing page."},{"id":"10186-q4-o2","label":"The current flight manual, cockpit placard/checklist and instructor brief for the booked aircraft."},{"id":"10186-q4-o3","label":"A figure remembered from another aircraft."},{"id":"10186-q4-o4","label":"An online forum post."}],"correctAnswer":"10186-q4-o2","required":true,"incorrectExplanation":"Review the lesson briefing, the current aircraft documents and the instructor-approved sequence before trying again.","successMessage":"Correct - relate the answer to the booked aircraft and the conditions on the day."}],"commonSources":[["NZ CAA Flight Instructor Guide briefing framework","https://www.aviation.govt.nz/licensing-and-certification/pilots/flight-training/flight-instructor-guide/briefings-introduction/"],["RAAus RPC syllabus","https://raaus.com.au/wp-content/uploads/2023/10/1-syllabus-of-flight-training-issue-7-v2-single-pages-1.pdf"],["RAAus Flight Operations Manual","https://raaus.com.au/wp-content/uploads/2024/07/RAAus-Flight-Operations-Manual.pdf"],["Tecnam P92 family overview - general information only","https://tecnam.com/aircraft/p92-echo-mkii/"]]},{"code":"1.01-8.5","title":"Circuits - Circuit Emergencies","sources":[["CAA engine failure after take-off","https://www.aviation.govt.nz/licensing-and-certification/pilots/flight-training/flight-instructor-guide/engine-failure-after-take-off/"],["CAA radio failure","https://www.aviation.govt.nz/licensing-and-certification/pilots/flight-training/flight-instructor-guide/radio-failure/"]],"outcomes":["Respond immediately to a simulated engine failure after take-off or in the circuit.","Select a survivable flight path before attempting checks or communication.","Manage circuit abnormalities using aircraft-control, analyse, action and communicate priorities."],"p92":["Use the exact P92 emergency checklist memory actions and follow-up checks approved for the booked aircraft.","Lower the nose promptly to preserve flying speed; do not attempt an unsafe turn-back.","Use only landing areas within the attainable forward sector unless the instructor’s scenario explicitly establishes otherwise.","Treat door, radio, flap and engine abnormalities according to the cockpit checklist and instructor brief."],"sequence":["Brief decision points, instructor simulation method, minimum heights and who will discontinue.","At the simulated failure: attitude for safe speed and choose the landing flight path.","Complete only the checks time and height permit; communicate if capacity remains.","Execute the instructor-directed recovery or go-around at the pre-briefed point.","Review the first three seconds: attitude, flight path and decision quality."],"threats":["Turn-back impulse: accept the area ahead and preserve control margins.","Checklist fixation: fly the aircraft and landing path before troubleshooting.","Startle and silence: use a rehearsed first-action sequence and clear verbal callouts."],"readiness":["I can state the first P92 actions from the current emergency checklist.","I understand the local take-off emergency brief and turn-back prohibition/criteria.","I know the instructor’s simulation and recovery call."],"questions":[{"prompt":"Following an engine failure after take-off, what is the immediate priority?","correct":"Set an attitude that preserves safe flying speed and select the landing path.","distractors":["Attempt a turn back regardless of height.","Troubleshoot every possible cause before lowering the nose.","Make a radio call before controlling airspeed."]},{"prompt":"Why are checks deliberately limited in a low-height emergency?","correct":"Time and height must be protected for aircraft control and landing.","distractors":["The P92 has no checklists.","Radio calls replace all checks.","Engine failures always correct themselves."]},{"prompt":"What should determine whether a simulated emergency continues?","correct":"The pre-briefed limits, aircraft state and instructor direction.","distractors":["A desire to complete the exercise at any cost.","The student’s willingness to descend below the limit.","Whether another lesson is booked."]}],"programIndex":8,"name":"RPC 08 - Circuits - Circuit Emergencies","quiz":[{"id":"10185-q1","type":"single_choice","prompt":"Following an engine failure after take-off, what is the immediate priority?","options":[{"id":"10185-q1-o1","label":"Set an attitude that preserves safe flying speed and select the landing path."},{"id":"10185-q1-o2","label":"Attempt a turn back regardless of height."},{"id":"10185-q1-o3","label":"Troubleshoot every possible cause before lowering the nose."},{"id":"10185-q1-o4","label":"Make a radio call before controlling airspeed."}],"correctAnswer":"10185-q1-o1","required":true,"incorrectExplanation":"Review the lesson briefing, the current aircraft documents and the instructor-approved sequence before trying again.","successMessage":"Correct - relate the answer to the booked aircraft and the conditions on the day."},{"id":"10185-q2","type":"single_choice","prompt":"Why are checks deliberately limited in a low-height emergency?","options":[{"id":"10185-q2-o1","label":"The P92 has no checklists."},{"id":"10185-q2-o2","label":"Radio calls replace all checks."},{"id":"10185-q2-o3","label":"Engine failures always correct themselves."},{"id":"10185-q2-o4","label":"Time and height must be protected for aircraft control and landing."}],"correctAnswer":"10185-q2-o4","required":true,"incorrectExplanation":"Review the lesson briefing, the current aircraft documents and the instructor-approved sequence before trying again.","successMessage":"Correct - relate the answer to the booked aircraft and the conditions on the day."},{"id":"10185-q3","type":"single_choice","prompt":"What should determine whether a simulated emergency continues?","options":[{"id":"10185-q3-o1","label":"The student’s willingness to descend below the limit."},{"id":"10185-q3-o2","label":"Whether another lesson is booked."},{"id":"10185-q3-o3","label":"The pre-briefed limits, aircraft state and instructor direction."},{"id":"10185-q3-o4","label":"A desire to complete the exercise at any cost."}],"correctAnswer":"10185-q3-o3","required":true,"incorrectExplanation":"Review the lesson briefing, the current aircraft documents and the instructor-approved sequence before trying again.","successMessage":"Correct - relate the answer to the booked aircraft and the conditions on the day."},{"id":"10185-q4","type":"single_choice","prompt":"Before using a P92 speed, RPM, flap setting, limitation or emergency action, which source controls?","options":[{"id":"10185-q4-o1","label":"The current Tecnam marketing page."},{"id":"10185-q4-o2","label":"The current flight manual, cockpit placard/checklist and instructor brief for the booked aircraft."},{"id":"10185-q4-o3","label":"A figure remembered from another aircraft."},{"id":"10185-q4-o4","label":"An online forum post."}],"correctAnswer":"10185-q4-o2","required":true,"incorrectExplanation":"Review the lesson briefing, the current aircraft documents and the instructor-approved sequence before trying again.","successMessage":"Correct - relate the answer to the booked aircraft and the conditions on the day."}],"commonSources":[["NZ CAA Flight Instructor Guide briefing framework","https://www.aviation.govt.nz/licensing-and-certification/pilots/flight-training/flight-instructor-guide/briefings-introduction/"],["RAAus RPC syllabus","https://raaus.com.au/wp-content/uploads/2023/10/1-syllabus-of-flight-training-issue-7-v2-single-pages-1.pdf"],["RAAus Flight Operations Manual","https://raaus.com.au/wp-content/uploads/2024/07/RAAus-Flight-Operations-Manual.pdf"],["Tecnam P92 family overview - general information only","https://tecnam.com/aircraft/p92-echo-mkii/"]]},{"code":"SOLO-1","title":"Circuit Consolidation - Supervised Circuits","sources":[["CAA circuit considerations","https://www.aviation.govt.nz/licensing-and-certification/pilots/flight-training/flight-instructor-guide/circuit-considerations/"],["CAA crosswind circuit","https://www.aviation.govt.nz/licensing-and-certification/pilots/flight-training/flight-instructor-guide/crosswind-circuit/"]],"outcomes":["Apply the authorised solo limits and make conservative command decisions.","Fly repeatable circuits, go around when required and report any abnormality.","Complete pre-flight, radio and post-flight duties without instructor prompting."],"p92":["Confirm the specific aircraft, fuel, loading, defects and cockpit checklist before accepting the flight.","Set the seat, restraints, controls and sight picture exactly as practised dual.","Use the authorised P92 circuit speeds and flap schedule; do not improvise.","After landing, taxi conservatively and report any hard landing, exceedance, defect or uncertainty."],"sequence":["Receive and repeat the instructor’s runway, wind, circuit, time and go-around limits.","Complete aircraft inspection, documents, fuel and cockpit preparation.","Fly the authorised number of circuits while maintaining listening watch and lookout.","Stop or go around whenever conditions, traffic or aircraft performance fall outside the brief.","Secure the aircraft and conduct an immediate instructor debrief and record update."],"threats":["Pressure to continue: the solo authorisation is conditional and may be declined or ended.","Changing wind or traffic: reassess on every circuit, not only before take-off.","Overconfidence after one good landing: use the same gates every time."],"readiness":["I can repeat every solo limitation and explain how I will monitor it.","I will go around or stop if I am uncertain.","I know how to contact the supervising instructor and report an abnormal event."],"questions":[{"prompt":"What happens if conditions move outside the instructor’s solo limits?","correct":"Go around, land or do not depart as appropriate, and contact the instructor.","distractors":["Continue because the original authorisation cannot change.","Change the limits yourself.","Turn off the radio and remain in circuit."]},{"prompt":"What should a solo student do after a suspected hard landing?","correct":"Stop as appropriate and report it before further flight.","distractors":["Continue without telling anyone if the aircraft taxies normally.","Delete the flight record.","Inspect only the tyres and depart again."]},{"prompt":"What is the purpose of repeating the solo brief back to the instructor?","correct":"To confirm shared understanding of the authority and limits.","distractors":["To replace the cockpit checklist.","To avoid checking the weather.","To authorise flight at any aerodrome."]}],"programIndex":9,"name":"RPC 09 - Circuit Consolidation - Supervised Circuits","quiz":[{"id":"solo1-q1","type":"single_choice","prompt":"What happens if conditions move outside the instructor’s solo limits?","options":[{"id":"solo1-q1-o1","label":"Change the limits yourself."},{"id":"solo1-q1-o2","label":"Turn off the radio and remain in circuit."},{"id":"solo1-q1-o3","label":"Go around, land or do not depart as appropriate, and contact the instructor."},{"id":"solo1-q1-o4","label":"Continue because the original authorisation cannot change."}],"correctAnswer":"solo1-q1-o3","required":true,"incorrectExplanation":"Review the lesson briefing, the current aircraft documents and the instructor-approved sequence before trying again.","successMessage":"Correct - relate the answer to the booked aircraft and the conditions on the day."},{"id":"solo1-q2","type":"single_choice","prompt":"What should a solo student do after a suspected hard landing?","options":[{"id":"solo1-q2-o1","label":"Inspect only the tyres and depart again."},{"id":"solo1-q2-o2","label":"Stop as appropriate and report it before further flight."},{"id":"solo1-q2-o3","label":"Continue without telling anyone if the aircraft taxies normally."},{"id":"solo1-q2-o4","label":"Delete the flight record."}],"correctAnswer":"solo1-q2-o2","required":true,"incorrectExplanation":"Review the lesson briefing, the current aircraft documents and the instructor-approved sequence before trying again.","successMessage":"Correct - relate the answer to the booked aircraft and the conditions on the day."},{"id":"solo1-q3","type":"single_choice","prompt":"What is the purpose of repeating the solo brief back to the instructor?","options":[{"id":"solo1-q3-o1","label":"To confirm shared understanding of the authority and limits."},{"id":"solo1-q3-o2","label":"To replace the cockpit checklist."},{"id":"solo1-q3-o3","label":"To avoid checking the weather."},{"id":"solo1-q3-o4","label":"To authorise flight at any aerodrome."}],"correctAnswer":"solo1-q3-o1","required":true,"incorrectExplanation":"Review the lesson briefing, the current aircraft documents and the instructor-approved sequence before trying again.","successMessage":"Correct - relate the answer to the booked aircraft and the conditions on the day."},{"id":"solo1-q4","type":"single_choice","prompt":"Before using a P92 speed, RPM, flap setting, limitation or emergency action, which source controls?","options":[{"id":"solo1-q4-o1","label":"A figure remembered from another aircraft."},{"id":"solo1-q4-o2","label":"An online forum post."},{"id":"solo1-q4-o3","label":"The current Tecnam marketing page."},{"id":"solo1-q4-o4","label":"The current flight manual, cockpit placard/checklist and instructor brief for the booked aircraft."}],"correctAnswer":"solo1-q4-o4","required":true,"incorrectExplanation":"Review the lesson briefing, the current aircraft documents and the instructor-approved sequence before trying again.","successMessage":"Correct - relate the answer to the booked aircraft and the conditions on the day."}],"commonSources":[["NZ CAA Flight Instructor Guide briefing framework","https://www.aviation.govt.nz/licensing-and-certification/pilots/flight-training/flight-instructor-guide/briefings-introduction/"],["RAAus RPC syllabus","https://raaus.com.au/wp-content/uploads/2023/10/1-syllabus-of-flight-training-issue-7-v2-single-pages-1.pdf"],["RAAus Flight Operations Manual","https://raaus.com.au/wp-content/uploads/2024/07/RAAus-Flight-Operations-Manual.pdf"],["Tecnam P92 family overview - general information only","https://tecnam.com/aircraft/p92-echo-mkii/"]]},{"code":"1.01-6A","title":"Advanced Turns","sources":[["CAA steep turns","https://www.aviation.govt.nz/licensing-and-certification/pilots/flight-training/flight-instructor-guide/steep-turns/"],["CAA maximum rate turns","https://www.aviation.govt.nz/licensing-and-certification/pilots/flight-training/flight-instructor-guide/maximum-rate-turns/"]],"outcomes":["Fly steep turns within the aircraft, CFI and lesson limits.","Manage the increased lift, drag, load factor and energy requirements.","Recognise and recover from developing spiral, climb, descent or coordination errors."],"p92":["Confirm the P92 manoeuvring and speed limitations before the exercise; remain within the permitted category and loading envelope.","Use coordinated roll entry, progressively adjust back pressure and power, and keep a strong horizon reference.","Avoid abrupt control inputs and do not chase altitude with excessive pitch near the speed margin.","Recover by reducing bank, managing pitch and power, and returning to a stable attitude."],"sequence":["Complete height, airspace, security, engine and lookout checks.","Establish entry speed and an outside reference.","Roll smoothly to the nominated bank, coordinate, adjust lift and power.","Maintain lookout through the turn and recognise performance trends early.","Lead recovery, level the wings, remove extra back pressure and stabilise."],"threats":["Load-factor and stall-speed increase: respect bank, speed and manoeuvre limits.","Spiral tendency: reduce bank before attempting a large pitch correction.","Lookout breakdown: use clearing turns and keep the scan moving through the turn."],"readiness":["I can explain why stall speed rises as load factor rises.","I know the approved P92 bank and speed limits for today’s exercise.","I can state the safe recovery priorities from a descending steep turn."],"questions":[{"prompt":"As load factor increases in a level turn, what happens to stall speed?","correct":"It increases.","distractors":["It decreases to zero.","It is unaffected in every case.","It becomes the maximum cruise speed."]},{"prompt":"If a steep turn develops into a descending spiral, what is the first control priority?","correct":"Reduce the bank before making a large pitch recovery.","distractors":["Pull back harder while maintaining bank.","Apply full rudder into the turn.","Extend flap at any speed."]},{"prompt":"Why may power be adjusted in a sustained steep level turn?","correct":"To offset increased drag while the required lift is maintained.","distractors":["To control radio volume.","To replace coordinated rudder.","To lower load factor without changing bank."]}],"programIndex":10,"name":"RPC 10 - Advanced Turns","quiz":[{"id":"1016a-q1","type":"single_choice","prompt":"As load factor increases in a level turn, what happens to stall speed?","options":[{"id":"1016a-q1-o1","label":"It becomes the maximum cruise speed."},{"id":"1016a-q1-o2","label":"It increases."},{"id":"1016a-q1-o3","label":"It decreases to zero."},{"id":"1016a-q1-o4","label":"It is unaffected in every case."}],"correctAnswer":"1016a-q1-o2","required":true,"incorrectExplanation":"Review the lesson briefing, the current aircraft documents and the instructor-approved sequence before trying again.","successMessage":"Correct - relate the answer to the booked aircraft and the conditions on the day."},{"id":"1016a-q2","type":"single_choice","prompt":"If a steep turn develops into a descending spiral, what is the first control priority?","options":[{"id":"1016a-q2-o1","label":"Reduce the bank before making a large pitch recovery."},{"id":"1016a-q2-o2","label":"Pull back harder while maintaining bank."},{"id":"1016a-q2-o3","label":"Apply full rudder into the turn."},{"id":"1016a-q2-o4","label":"Extend flap at any speed."}],"correctAnswer":"1016a-q2-o1","required":true,"incorrectExplanation":"Review the lesson briefing, the current aircraft documents and the instructor-approved sequence before trying again.","successMessage":"Correct - relate the answer to the booked aircraft and the conditions on the day."},{"id":"1016a-q3","type":"single_choice","prompt":"Why may power be adjusted in a sustained steep level turn?","options":[{"id":"1016a-q3-o1","label":"To control radio volume."},{"id":"1016a-q3-o2","label":"To replace coordinated rudder."},{"id":"1016a-q3-o3","label":"To lower load factor without changing bank."},{"id":"1016a-q3-o4","label":"To offset increased drag while the required lift is maintained."}],"correctAnswer":"1016a-q3-o4","required":true,"incorrectExplanation":"Review the lesson briefing, the current aircraft documents and the instructor-approved sequence before trying again.","successMessage":"Correct - relate the answer to the booked aircraft and the conditions on the day."},{"id":"1016a-q4","type":"single_choice","prompt":"Before using a P92 speed, RPM, flap setting, limitation or emergency action, which source controls?","options":[{"id":"1016a-q4-o1","label":"An online forum post."},{"id":"1016a-q4-o2","label":"The current Tecnam marketing page."},{"id":"1016a-q4-o3","label":"The current flight manual, cockpit placard/checklist and instructor brief for the booked aircraft."},{"id":"1016a-q4-o4","label":"A figure remembered from another aircraft."}],"correctAnswer":"1016a-q4-o3","required":true,"incorrectExplanation":"Review the lesson briefing, the current aircraft documents and the instructor-approved sequence before trying again.","successMessage":"Correct - relate the answer to the booked aircraft and the conditions on the day."}],"commonSources":[["NZ CAA Flight Instructor Guide briefing framework","https://www.aviation.govt.nz/licensing-and-certification/pilots/flight-training/flight-instructor-guide/briefings-introduction/"],["RAAus RPC syllabus","https://raaus.com.au/wp-content/uploads/2023/10/1-syllabus-of-flight-training-issue-7-v2-single-pages-1.pdf"],["RAAus Flight Operations Manual","https://raaus.com.au/wp-content/uploads/2024/07/RAAus-Flight-Operations-Manual.pdf"],["Tecnam P92 family overview - general information only","https://tecnam.com/aircraft/p92-echo-mkii/"]]},{"code":"1.01-7S","title":"Scenario-Based Stalls","sources":[["CAA advanced stalling","https://www.aviation.govt.nz/licensing-and-certification/pilots/flight-training/flight-instructor-guide/advanced-stalling/"],["CAA wing-drop stalling","https://www.aviation.govt.nz/licensing-and-certification/pilots/flight-training/flight-instructor-guide/wing-drop-stalling/"]],"outcomes":["Recognise stall precursors inside realistic circuit and operational scenarios.","Prevent the stall where possible and recover at the earliest cue.","Control yaw, avoid secondary stall and make a sound post-recovery decision."],"p92":["Use only configurations and profiles approved for the P92 Echo Super by the current flight manual and CFI.","Emphasise base-to-final overshoot, distraction, go-around configuration and power-change scenarios without creating an unsafe state.","Reduce angle of attack and control yaw; use aileron only as appropriate to the aircraft state and instructor brief.","After recovery, choose whether to go around, discontinue or reconfigure instead of automatically resuming the scenario."],"sequence":["Brief the scenario, expected cues, recovery gate and minimum height.","Establish the approved configuration and introduce one operational threat.","Identify trend toward excessive angle of attack or poor coordination.","Prevent or recover using unload, yaw control, power and flight-path recovery.","Stabilise, check height and aircraft state, then make the next operational decision."],"threats":["Base-to-final skid: never use excess inside rudder to force the aircraft around.","Secondary stall: recover the flight path progressively after angle-of-attack reduction.","Scenario fixation: discontinue immediately if the aircraft response differs from the brief."],"readiness":["I can identify the control error that makes a base-to-final skid hazardous.","I know the difference between stall prevention and recovery.","I understand the exercise is not spin training."],"questions":[{"prompt":"Why is excess inside rudder during a base-to-final overshoot dangerous near the stall?","correct":"It can create a skid, yaw and rapid wing drop toward an incipient spin.","distractors":["It always improves turn performance safely.","It prevents the critical angle of attack.","It automatically levels the wings."]},{"prompt":"After the wing is unstalled, what should prevent a secondary stall?","correct":"Progressive flight-path recovery without excessive back pressure.","distractors":["An immediate abrupt pull-up.","Full opposite rudder held indefinitely.","Ignoring airspeed and attitude."]},{"prompt":"If the scenario develops differently from the brief, what should happen?","correct":"Discontinue or recover immediately as directed.","distractors":["Continue until the planned cue appears.","Descend below the minimum height.","Add more control input to force the expected result."]}],"programIndex":11,"name":"RPC 11 - Scenario-Based Stalls","quiz":[{"id":"1017s-q1","type":"single_choice","prompt":"Why is excess inside rudder during a base-to-final overshoot dangerous near the stall?","options":[{"id":"1017s-q1-o1","label":"It automatically levels the wings."},{"id":"1017s-q1-o2","label":"It can create a skid, yaw and rapid wing drop toward an incipient spin."},{"id":"1017s-q1-o3","label":"It always improves turn performance safely."},{"id":"1017s-q1-o4","label":"It prevents the critical angle of attack."}],"correctAnswer":"1017s-q1-o2","required":true,"incorrectExplanation":"Review the lesson briefing, the current aircraft documents and the instructor-approved sequence before trying again.","successMessage":"Correct - relate the answer to the booked aircraft and the conditions on the day."},{"id":"1017s-q2","type":"single_choice","prompt":"After the wing is unstalled, what should prevent a secondary stall?","options":[{"id":"1017s-q2-o1","label":"Progressive flight-path recovery without excessive back pressure."},{"id":"1017s-q2-o2","label":"An immediate abrupt pull-up."},{"id":"1017s-q2-o3","label":"Full opposite rudder held indefinitely."},{"id":"1017s-q2-o4","label":"Ignoring airspeed and attitude."}],"correctAnswer":"1017s-q2-o1","required":true,"incorrectExplanation":"Review the lesson briefing, the current aircraft documents and the instructor-approved sequence before trying again.","successMessage":"Correct - relate the answer to the booked aircraft and the conditions on the day."},{"id":"1017s-q3","type":"single_choice","prompt":"If the scenario develops differently from the brief, what should happen?","options":[{"id":"1017s-q3-o1","label":"Continue until the planned cue appears."},{"id":"1017s-q3-o2","label":"Descend below the minimum height."},{"id":"1017s-q3-o3","label":"Add more control input to force the expected result."},{"id":"1017s-q3-o4","label":"Discontinue or recover immediately as directed."}],"correctAnswer":"1017s-q3-o4","required":true,"incorrectExplanation":"Review the lesson briefing, the current aircraft documents and the instructor-approved sequence before trying again.","successMessage":"Correct - relate the answer to the booked aircraft and the conditions on the day."},{"id":"1017s-q4","type":"single_choice","prompt":"Before using a P92 speed, RPM, flap setting, limitation or emergency action, which source controls?","options":[{"id":"1017s-q4-o1","label":"An online forum post."},{"id":"1017s-q4-o2","label":"The current Tecnam marketing page."},{"id":"1017s-q4-o3","label":"The current flight manual, cockpit placard/checklist and instructor brief for the booked aircraft."},{"id":"1017s-q4-o4","label":"A figure remembered from another aircraft."}],"correctAnswer":"1017s-q4-o3","required":true,"incorrectExplanation":"Review the lesson briefing, the current aircraft documents and the instructor-approved sequence before trying again.","successMessage":"Correct - relate the answer to the booked aircraft and the conditions on the day."}],"commonSources":[["NZ CAA Flight Instructor Guide briefing framework","https://www.aviation.govt.nz/licensing-and-certification/pilots/flight-training/flight-instructor-guide/briefings-introduction/"],["RAAus RPC syllabus","https://raaus.com.au/wp-content/uploads/2023/10/1-syllabus-of-flight-training-issue-7-v2-single-pages-1.pdf"],["RAAus Flight Operations Manual","https://raaus.com.au/wp-content/uploads/2024/07/RAAus-Flight-Operations-Manual.pdf"],["Tecnam P92 family overview - general information only","https://tecnam.com/aircraft/p92-echo-mkii/"]]},{"code":"1.01-10 / 2.04","title":"Training Area Operations and Radio Procedures","sources":[["CAA vacating and joining at aerodromes","https://www.aviation.govt.nz/licensing-and-certification/pilots/flight-training/flight-instructor-guide/vacating-and-joining-at-aerodromes/"],["CAA radio failure","https://www.aviation.govt.nz/licensing-and-certification/pilots/flight-training/flight-instructor-guide/radio-failure/"]],"outcomes":["Depart, orientate in and return from the local training area using approved routes.","Make concise radio calls, maintain listening watch and integrate with traffic.","Maintain airspace, weather, fuel and position awareness throughout."],"p92":["Configure the P92 avionics, intercom, transponder and radio from the installed-equipment checklist; panels may differ between club aircraft.","Set frequencies and transponder codes before high-workload phases where practical.","Use the high-wing view deliberately: clear around wing and door-frame blind areas during turns and joins.","Cross-check fuel selection/quantity and engine indications at planned gates."],"sequence":["Brief runway, departure route, airspace, training area boundaries and return points.","Set radio and transponder, make departure calls and maintain traffic separation.","Identify landmarks and continuously update position, altitude, weather and fuel.","Plan the return early, obtain traffic information and make the required inbound call.","Join using the approved local procedure and integrate predictably with other traffic."],"threats":["Head-down radio work: aviate and look out; delay nonessential setup.","Confirmation bias in landmark identification: use more than one distinguishing feature.","Frequency or call error: pause, correct clearly and continue listening."],"readiness":["I can draw the BFC training area boundaries and local departure/arrival routes.","I can make the expected calls in plain, concise standard phraseology.","I know the radio-failure actions and local non-towered procedure."],"questions":[{"prompt":"What is the first priority if radio setup begins to compromise lookout or control?","correct":"Fly the aircraft and restore situational awareness.","distractors":["Keep programming until complete.","Descend to improve reception.","Stop listening for traffic."]},{"prompt":"How should a landmark be positively identified?","correct":"By matching multiple distinguishing features and expected position.","distractors":["By choosing the first feature that resembles the map.","By ignoring elapsed time.","By relying only on GPS track colour."]},{"prompt":"What makes a useful non-towered radio call?","correct":"Correct location, aircraft identity, position/level and intentions, stated concisely.","distractors":["A long explanation of the entire flight.","Only the aircraft registration.","A call transmitted without first listening."]}],"programIndex":12,"name":"RPC 12 - Training Area Operations and Radio Procedures","quiz":[{"id":"10110204-q1","type":"single_choice","prompt":"What is the first priority if radio setup begins to compromise lookout or control?","options":[{"id":"10110204-q1-o1","label":"Descend to improve reception."},{"id":"10110204-q1-o2","label":"Stop listening for traffic."},{"id":"10110204-q1-o3","label":"Fly the aircraft and restore situational awareness."},{"id":"10110204-q1-o4","label":"Keep programming until complete."}],"correctAnswer":"10110204-q1-o3","required":true,"incorrectExplanation":"Review the lesson briefing, the current aircraft documents and the instructor-approved sequence before trying again.","successMessage":"Correct - relate the answer to the booked aircraft and the conditions on the day."},{"id":"10110204-q2","type":"single_choice","prompt":"How should a landmark be positively identified?","options":[{"id":"10110204-q2-o1","label":"By relying only on GPS track colour."},{"id":"10110204-q2-o2","label":"By matching multiple distinguishing features and expected position."},{"id":"10110204-q2-o3","label":"By choosing the first feature that resembles the map."},{"id":"10110204-q2-o4","label":"By ignoring elapsed time."}],"correctAnswer":"10110204-q2-o2","required":true,"incorrectExplanation":"Review the lesson briefing, the current aircraft documents and the instructor-approved sequence before trying again.","successMessage":"Correct - relate the answer to the booked aircraft and the conditions on the day."},{"id":"10110204-q3","type":"single_choice","prompt":"What makes a useful non-towered radio call?","options":[{"id":"10110204-q3-o1","label":"Correct location, aircraft identity, position/level and intentions, stated concisely."},{"id":"10110204-q3-o2","label":"A long explanation of the entire flight."},{"id":"10110204-q3-o3","label":"Only the aircraft registration."},{"id":"10110204-q3-o4","label":"A call transmitted without first listening."}],"correctAnswer":"10110204-q3-o1","required":true,"incorrectExplanation":"Review the lesson briefing, the current aircraft documents and the instructor-approved sequence before trying again.","successMessage":"Correct - relate the answer to the booked aircraft and the conditions on the day."},{"id":"10110204-q4","type":"single_choice","prompt":"Before using a P92 speed, RPM, flap setting, limitation or emergency action, which source controls?","options":[{"id":"10110204-q4-o1","label":"A figure remembered from another aircraft."},{"id":"10110204-q4-o2","label":"An online forum post."},{"id":"10110204-q4-o3","label":"The current Tecnam marketing page."},{"id":"10110204-q4-o4","label":"The current flight manual, cockpit placard/checklist and instructor brief for the booked aircraft."}],"correctAnswer":"10110204-q4-o4","required":true,"incorrectExplanation":"Review the lesson briefing, the current aircraft documents and the instructor-approved sequence before trying again.","successMessage":"Correct - relate the answer to the booked aircraft and the conditions on the day."}],"commonSources":[["NZ CAA Flight Instructor Guide briefing framework","https://www.aviation.govt.nz/licensing-and-certification/pilots/flight-training/flight-instructor-guide/briefings-introduction/"],["RAAus RPC syllabus","https://raaus.com.au/wp-content/uploads/2023/10/1-syllabus-of-flight-training-issue-7-v2-single-pages-1.pdf"],["RAAus Flight Operations Manual","https://raaus.com.au/wp-content/uploads/2024/07/RAAus-Flight-Operations-Manual.pdf"],["Tecnam P92 family overview - general information only","https://tecnam.com/aircraft/p92-echo-mkii/"]]},{"code":"1.01-9.2/9.3","title":"Forced Landing, Glide Approaches and Sideslip Awareness","sources":[["CAA forced landing pattern","https://www.aviation.govt.nz/licensing-and-certification/pilots/flight-training/flight-instructor-guide/forced-landing-without-power-pattern/"],["CAA forced landing considerations","https://www.aviation.govt.nz/licensing-and-certification/pilots/flight-training/flight-instructor-guide/forced-landing-without-power-considerations/"],["CAA glide approach","https://www.aviation.govt.nz/licensing-and-certification/pilots/flight-training/flight-instructor-guide/glide-approach/"]],"outcomes":["Select a suitable landing area and plan a controllable glide pattern.","Prioritise attitude and flight path before checks, communication and preparation.","Use sideslip only when approved, briefed and appropriate to the P92 configuration."],"p92":["Use the current P92 best-glide figure and emergency checklist; do not rely on a figure from another club aircraft.","Maintain coordinated flight unless a deliberate, approved sideslip is being demonstrated.","Confirm any P92 limitations on prolonged sideslip, flap combination and fuel state before the exercise.","Recover at the instructor’s nominated minimum height; the objective is judgement and procedure, not landing off-field."],"sequence":["At simulated power loss: set glide attitude, choose field and plan the pattern.","Assess wind, surface, slope, obstacles, sun and overshoot/undershoot options.","Position using key points or the CFI-approved pattern while maintaining lookout.","Complete restart checks, mayday, passenger brief and shutdown items only as time permits.","At the recovery gate, go around smoothly and review whether the field remained reachable."],"threats":["Best-field fixation: choose early, then change only for a clearly better and reachable option.","Checklist tunnelling: maintain glide attitude, field position and lookout.","Excessive sideslip or low recovery: remain within aircraft and instructor limits."],"readiness":["I know where to find the booked aircraft’s glide figure and restart checks.","I can state the field-selection factors and the planned pattern.","I know the minimum recovery height and who calls the go-around."],"questions":[{"prompt":"Immediately after a simulated engine failure away from the circuit, what should be established first?","correct":"The glide attitude and a reachable landing plan.","distractors":["A complete mayday call.","Every restart checklist item.","A sideslip."]},{"prompt":"What is the purpose of the forced-landing pattern?","correct":"To manage position and energy so the selected area remains reachable.","distractors":["To guarantee a landing in any field.","To eliminate the need to assess wind.","To keep the aircraft directly above the field."]},{"prompt":"When is sideslip acceptable in this lesson?","correct":"Only when aircraft-approved, instructor-briefed and operationally appropriate.","distractors":["At any speed and flap setting.","Whenever the aircraft is high, without checking limitations.","As a replacement for a go-around."]}],"programIndex":13,"name":"RPC 13 - Forced Landing, Glide Approaches and Sideslip Awareness","quiz":[{"id":"1019293-q1","type":"single_choice","prompt":"Immediately after a simulated engine failure away from the circuit, what should be established first?","options":[{"id":"1019293-q1-o1","label":"The glide attitude and a reachable landing plan."},{"id":"1019293-q1-o2","label":"A complete mayday call."},{"id":"1019293-q1-o3","label":"Every restart checklist item."},{"id":"1019293-q1-o4","label":"A sideslip."}],"correctAnswer":"1019293-q1-o1","required":true,"incorrectExplanation":"Review the lesson briefing, the current aircraft documents and the instructor-approved sequence before trying again.","successMessage":"Correct - relate the answer to the booked aircraft and the conditions on the day."},{"id":"1019293-q2","type":"single_choice","prompt":"What is the purpose of the forced-landing pattern?","options":[{"id":"1019293-q2-o1","label":"To guarantee a landing in any field."},{"id":"1019293-q2-o2","label":"To eliminate the need to assess wind."},{"id":"1019293-q2-o3","label":"To keep the aircraft directly above the field."},{"id":"1019293-q2-o4","label":"To manage position and energy so the selected area remains reachable."}],"correctAnswer":"1019293-q2-o4","required":true,"incorrectExplanation":"Review the lesson briefing, the current aircraft documents and the instructor-approved sequence before trying again.","successMessage":"Correct - relate the answer to the booked aircraft and the conditions on the day."},{"id":"1019293-q3","type":"single_choice","prompt":"When is sideslip acceptable in this lesson?","options":[{"id":"1019293-q3-o1","label":"Whenever the aircraft is high, without checking limitations."},{"id":"1019293-q3-o2","label":"As a replacement for a go-around."},{"id":"1019293-q3-o3","label":"Only when aircraft-approved, instructor-briefed and operationally appropriate."},{"id":"1019293-q3-o4","label":"At any speed and flap setting."}],"correctAnswer":"1019293-q3-o3","required":true,"incorrectExplanation":"Review the lesson briefing, the current aircraft documents and the instructor-approved sequence before trying again.","successMessage":"Correct - relate the answer to the booked aircraft and the conditions on the day."},{"id":"1019293-q4","type":"single_choice","prompt":"Before using a P92 speed, RPM, flap setting, limitation or emergency action, which source controls?","options":[{"id":"1019293-q4-o1","label":"The current Tecnam marketing page."},{"id":"1019293-q4-o2","label":"The current flight manual, cockpit placard/checklist and instructor brief for the booked aircraft."},{"id":"1019293-q4-o3","label":"A figure remembered from another aircraft."},{"id":"1019293-q4-o4","label":"An online forum post."}],"correctAnswer":"1019293-q4-o2","required":true,"incorrectExplanation":"Review the lesson briefing, the current aircraft documents and the instructor-approved sequence before trying again.","successMessage":"Correct - relate the answer to the booked aircraft and the conditions on the day."}],"commonSources":[["NZ CAA Flight Instructor Guide briefing framework","https://www.aviation.govt.nz/licensing-and-certification/pilots/flight-training/flight-instructor-guide/briefings-introduction/"],["RAAus RPC syllabus","https://raaus.com.au/wp-content/uploads/2023/10/1-syllabus-of-flight-training-issue-7-v2-single-pages-1.pdf"],["RAAus Flight Operations Manual","https://raaus.com.au/wp-content/uploads/2024/07/RAAus-Flight-Operations-Manual.pdf"],["Tecnam P92 family overview - general information only","https://tecnam.com/aircraft/p92-echo-mkii/"]]},{"code":"1.01-9.4","title":"Precautionary Search and Landing","sources":[["CAA precautionary landing","https://www.aviation.govt.nz/licensing-and-certification/pilots/flight-training/flight-instructor-guide/precautionary-landing/"],["CAA terrain and weather awareness","https://www.aviation.govt.nz/licensing-and-certification/pilots/flight-training/flight-instructor-guide/terrain-and-weather-awareness/"]],"outcomes":["Recognise when deteriorating conditions justify diversion or precautionary landing.","Assess a candidate area systematically without allowing low-level task saturation.","Make an early continue, divert, land or abandon decision."],"p92":["Use current P92 performance data with actual weight, wind, surface and obstacle factors; brochure figures are not planning data.","Configure only as authorised for each inspection stage and protect airspeed, bank and escape options.","Use the high-wing visibility while deliberately clearing the wing-obscured side before every turn.","This lesson is not a low-flying endorsement and does not authorise flight below applicable limits."],"sequence":["Identify the trigger for precautionary action and compare safer alternatives first.","Select a candidate area using wind, length, slope, surface, obstacles and go-around path.","Plan inspection passes only at CFI-approved heights and configuration.","Maintain a stable track, lookout and escape option while gathering only useful information.","Decide early: land, divert, choose another area or abandon the inspection."],"threats":["Get-there-itis: diversion or landing is successful risk management, not failure.","Low-level fixation: fly the aircraft and escape path before examining details.","Repeated passes: each pass adds exposure; set a decision limit before starting."],"readiness":["I can list the reasons for a precautionary landing and safer alternatives.","I can brief inspection objectives, heights and go-around path.","I understand no online lesson authorises low flying."],"questions":[{"prompt":"What should be considered before beginning a precautionary inspection?","correct":"Whether an earlier diversion or known aerodrome is safer.","distractors":["How many low passes can be flown.","Whether radio calls can be avoided.","How to continue regardless of weather."]},{"prompt":"What must every inspection pass preserve?","correct":"Airspeed, lookout, obstacle clearance and a viable escape path.","distractors":["The lowest possible height.","A steep bank around the field.","A fixed plan to land."]},{"prompt":"Why should the number of inspection passes be limited?","correct":"Repeated low-level exposure increases workload and risk.","distractors":["The P92 can only turn twice.","The radio stops working after three passes.","Wind cannot be assessed twice."]}],"programIndex":14,"name":"RPC 14 - Precautionary Search and Landing","quiz":[{"id":"10194-q1","type":"single_choice","prompt":"What should be considered before beginning a precautionary inspection?","options":[{"id":"10194-q1-o1","label":"Whether an earlier diversion or known aerodrome is safer."},{"id":"10194-q1-o2","label":"How many low passes can be flown."},{"id":"10194-q1-o3","label":"Whether radio calls can be avoided."},{"id":"10194-q1-o4","label":"How to continue regardless of weather."}],"correctAnswer":"10194-q1-o1","required":true,"incorrectExplanation":"Review the lesson briefing, the current aircraft documents and the instructor-approved sequence before trying again.","successMessage":"Correct - relate the answer to the booked aircraft and the conditions on the day."},{"id":"10194-q2","type":"single_choice","prompt":"What must every inspection pass preserve?","options":[{"id":"10194-q2-o1","label":"The lowest possible height."},{"id":"10194-q2-o2","label":"A steep bank around the field."},{"id":"10194-q2-o3","label":"A fixed plan to land."},{"id":"10194-q2-o4","label":"Airspeed, lookout, obstacle clearance and a viable escape path."}],"correctAnswer":"10194-q2-o4","required":true,"incorrectExplanation":"Review the lesson briefing, the current aircraft documents and the instructor-approved sequence before trying again.","successMessage":"Correct - relate the answer to the booked aircraft and the conditions on the day."},{"id":"10194-q3","type":"single_choice","prompt":"Why should the number of inspection passes be limited?","options":[{"id":"10194-q3-o1","label":"The radio stops working after three passes."},{"id":"10194-q3-o2","label":"Wind cannot be assessed twice."},{"id":"10194-q3-o3","label":"Repeated low-level exposure increases workload and risk."},{"id":"10194-q3-o4","label":"The P92 can only turn twice."}],"correctAnswer":"10194-q3-o3","required":true,"incorrectExplanation":"Review the lesson briefing, the current aircraft documents and the instructor-approved sequence before trying again.","successMessage":"Correct - relate the answer to the booked aircraft and the conditions on the day."},{"id":"10194-q4","type":"single_choice","prompt":"Before using a P92 speed, RPM, flap setting, limitation or emergency action, which source controls?","options":[{"id":"10194-q4-o1","label":"The current Tecnam marketing page."},{"id":"10194-q4-o2","label":"The current flight manual, cockpit placard/checklist and instructor brief for the booked aircraft."},{"id":"10194-q4-o3","label":"A figure remembered from another aircraft."},{"id":"10194-q4-o4","label":"An online forum post."}],"correctAnswer":"10194-q4-o2","required":true,"incorrectExplanation":"Review the lesson briefing, the current aircraft documents and the instructor-approved sequence before trying again.","successMessage":"Correct - relate the answer to the booked aircraft and the conditions on the day."}],"commonSources":[["NZ CAA Flight Instructor Guide briefing framework","https://www.aviation.govt.nz/licensing-and-certification/pilots/flight-training/flight-instructor-guide/briefings-introduction/"],["RAAus RPC syllabus","https://raaus.com.au/wp-content/uploads/2023/10/1-syllabus-of-flight-training-issue-7-v2-single-pages-1.pdf"],["RAAus Flight Operations Manual","https://raaus.com.au/wp-content/uploads/2024/07/RAAus-Flight-Operations-Manual.pdf"],["Tecnam P92 family overview - general information only","https://tecnam.com/aircraft/p92-echo-mkii/"]]},{"code":"1.01-11","title":"Abnormal Situations and Emergency Management","sources":[["CAA radio failure","https://www.aviation.govt.nz/licensing-and-certification/pilots/flight-training/flight-instructor-guide/radio-failure/"],["CAA unusual attitudes","https://www.aviation.govt.nz/licensing-and-certification/pilots/flight-training/flight-instructor-guide/unusual-attitudes/"]],"outcomes":["Recognise abnormal indications and apply a disciplined response.","Prioritise aircraft control, suitable landing options and checklist use.","Communicate, divert and report according to the situation."],"p92":["Locate the booked P92’s engine, fuel, electrical, fire, door and radio abnormal checklists; equipment differs across the fleet.","Know which indications require immediate action and which permit time for diagnosis.","For Rotax engine abnormalities, use the aircraft checklist and limitations rather than habits from conventional aero engines.","After any exceedance or suspected defect, stop further operation and report it through the portal and to staff."],"sequence":["Recognise the cue, maintain control and state the immediate threat.","Choose a safe flight path and landing/diversion option.","Apply memory actions only where authorised, then use the checklist.","Communicate with ATS/traffic and passengers as workload permits.","Land or continue only when justified, then secure, report and record."],"threats":["Startle response: use “aviate, navigate, communicate” to restore priorities.","Confirmation bias: verify the indication using independent cues before unnecessary action.","Reset-and-forget behaviour: do not repeatedly reset protection devices or conceal an intermittent fault."],"readiness":["I can locate the P92 emergency checklist without searching through unrelated pages.","I can explain when to land as soon as possible versus as soon as practical.","I know how to report a defect and safety occurrence after landing."],"questions":[{"prompt":"What is the correct first response to an unexpected abnormal indication?","correct":"Maintain aircraft control, assess the immediate threat and protect the flight path.","distractors":["Reset every switch immediately.","Continue without cross-checking.","Make a long radio call before flying the aircraft."]},{"prompt":"Why should a tripped circuit protection device not be repeatedly reset?","correct":"The underlying fault may create overheating or fire risk.","distractors":["It will improve radio range.","It always drains fuel.","It changes flap angle."]},{"prompt":"What should happen after a suspected aircraft exceedance or defect?","correct":"Stop further operation as appropriate and report it accurately.","distractors":["Fly again to see if it repeats.","Remove the evidence from the log.","Tell only another student."]}],"programIndex":15,"name":"RPC 15 - Abnormal Situations and Emergency Management","quiz":[{"id":"10111-q1","type":"single_choice","prompt":"What is the correct first response to an unexpected abnormal indication?","options":[{"id":"10111-q1-o1","label":"Make a long radio call before flying the aircraft."},{"id":"10111-q1-o2","label":"Maintain aircraft control, assess the immediate threat and protect the flight path."},{"id":"10111-q1-o3","label":"Reset every switch immediately."},{"id":"10111-q1-o4","label":"Continue without cross-checking."}],"correctAnswer":"10111-q1-o2","required":true,"incorrectExplanation":"Review the lesson briefing, the current aircraft documents and the instructor-approved sequence before trying again.","successMessage":"Correct - relate the answer to the booked aircraft and the conditions on the day."},{"id":"10111-q2","type":"single_choice","prompt":"Why should a tripped circuit protection device not be repeatedly reset?","options":[{"id":"10111-q2-o1","label":"The underlying fault may create overheating or fire risk."},{"id":"10111-q2-o2","label":"It will improve radio range."},{"id":"10111-q2-o3","label":"It always drains fuel."},{"id":"10111-q2-o4","label":"It changes flap angle."}],"correctAnswer":"10111-q2-o1","required":true,"incorrectExplanation":"Review the lesson briefing, the current aircraft documents and the instructor-approved sequence before trying again.","successMessage":"Correct - relate the answer to the booked aircraft and the conditions on the day."},{"id":"10111-q3","type":"single_choice","prompt":"What should happen after a suspected aircraft exceedance or defect?","options":[{"id":"10111-q3-o1","label":"Fly again to see if it repeats."},{"id":"10111-q3-o2","label":"Remove the evidence from the log."},{"id":"10111-q3-o3","label":"Tell only another student."},{"id":"10111-q3-o4","label":"Stop further operation as appropriate and report it accurately."}],"correctAnswer":"10111-q3-o4","required":true,"incorrectExplanation":"Review the lesson briefing, the current aircraft documents and the instructor-approved sequence before trying again.","successMessage":"Correct - relate the answer to the booked aircraft and the conditions on the day."},{"id":"10111-q4","type":"single_choice","prompt":"Before using a P92 speed, RPM, flap setting, limitation or emergency action, which source controls?","options":[{"id":"10111-q4-o1","label":"An online forum post."},{"id":"10111-q4-o2","label":"The current Tecnam marketing page."},{"id":"10111-q4-o3","label":"The current flight manual, cockpit placard/checklist and instructor brief for the booked aircraft."},{"id":"10111-q4-o4","label":"A figure remembered from another aircraft."}],"correctAnswer":"10111-q4-o3","required":true,"incorrectExplanation":"Review the lesson briefing, the current aircraft documents and the instructor-approved sequence before trying again.","successMessage":"Correct - relate the answer to the booked aircraft and the conditions on the day."}],"commonSources":[["NZ CAA Flight Instructor Guide briefing framework","https://www.aviation.govt.nz/licensing-and-certification/pilots/flight-training/flight-instructor-guide/briefings-introduction/"],["RAAus RPC syllabus","https://raaus.com.au/wp-content/uploads/2023/10/1-syllabus-of-flight-training-issue-7-v2-single-pages-1.pdf"],["RAAus Flight Operations Manual","https://raaus.com.au/wp-content/uploads/2024/07/RAAus-Flight-Operations-Manual.pdf"],["Tecnam P92 family overview - general information only","https://tecnam.com/aircraft/p92-echo-mkii/"]]},{"code":"RPC-CONSOL","title":"RPC Consolidation - Flight Test Profile Practice","sources":[["CAA briefing framework","https://www.aviation.govt.nz/licensing-and-certification/pilots/flight-training/flight-instructor-guide/briefings-introduction/"],["RAAus syllabus","https://raaus.com.au/wp-content/uploads/2023/10/1-syllabus-of-flight-training-issue-7-v2-single-pages-1.pdf"]],"outcomes":["Plan and fly a representative RPC profile with minimal instructor prompting.","Integrate normal handling, circuits, stalls, forced landing and abnormal scenarios.","Self-assess against Pilot Certificate command and consistency standards."],"p92":["Prepare one complete P92 operating-data set for the booked registration: loading, fuel, performance, limitations and defects.","Use one consistent cockpit flow backed by the current checklist; never substitute memorised figures from another P92.","Manage energy and configuration early enough that each manoeuvre begins stable.","Treat every instructor intervention as evidence to analyse, not merely a mark to hide."],"sequence":["Complete weather, NOTAM, airspace, fuel, loading and aircraft status planning.","Brief departure and demonstrate normal handling and advanced turns.","Complete scenario stall, forced landing and abnormal-event exercises.","Return for normal, flapless or emergency circuit elements as directed.","Secure the aircraft, complete records and lead an evidence-based self-debrief."],"threats":["Test-profile memorisation: respond to actual conditions and instructor scenarios.","Cumulative workload: reset priorities and stabilise between exercises.","Hiding uncertainty: verbalise decisions so gaps can be corrected before test."],"readiness":["I can complete the full planning package without missing an operational item.","I can recover from an imperfect manoeuvre without losing command judgement.","I can identify three specific remaining gaps and a plan for each."],"questions":[{"prompt":"What best demonstrates readiness during a consolidation flight?","correct":"Consistent command decisions and recovery from changing conditions without instructional assistance.","distractors":["Memorising a fixed sequence regardless of conditions.","Completing every manoeuvre once with no self-critique.","Avoiding all verbal decision making."]},{"prompt":"How should an error between exercises be managed?","correct":"Stabilise, identify the cause, correct priorities and continue only when ready.","distractors":["Rush directly into the next exercise.","Ignore it if altitude was regained.","Change the aircraft checklist."]},{"prompt":"Why is the self-debrief part of command readiness?","correct":"It shows the pilot can recognise evidence, risk and targeted improvement needs.","distractors":["It replaces instructor assessment.","It guarantees a flight-test pass.","It removes the need for records."]}],"programIndex":16,"name":"RPC 16 - RPC Consolidation - Flight Test Profile Practice","quiz":[{"id":"rpcconsol-q1","type":"single_choice","prompt":"What best demonstrates readiness during a consolidation flight?","options":[{"id":"rpcconsol-q1-o1","label":"Completing every manoeuvre once with no self-critique."},{"id":"rpcconsol-q1-o2","label":"Avoiding all verbal decision making."},{"id":"rpcconsol-q1-o3","label":"Consistent command decisions and recovery from changing conditions without instructional assistance."},{"id":"rpcconsol-q1-o4","label":"Memorising a fixed sequence regardless of conditions."}],"correctAnswer":"rpcconsol-q1-o3","required":true,"incorrectExplanation":"Review the lesson briefing, the current aircraft documents and the instructor-approved sequence before trying again.","successMessage":"Correct - relate the answer to the booked aircraft and the conditions on the day."},{"id":"rpcconsol-q2","type":"single_choice","prompt":"How should an error between exercises be managed?","options":[{"id":"rpcconsol-q2-o1","label":"Change the aircraft checklist."},{"id":"rpcconsol-q2-o2","label":"Stabilise, identify the cause, correct priorities and continue only when ready."},{"id":"rpcconsol-q2-o3","label":"Rush directly into the next exercise."},{"id":"rpcconsol-q2-o4","label":"Ignore it if altitude was regained."}],"correctAnswer":"rpcconsol-q2-o2","required":true,"incorrectExplanation":"Review the lesson briefing, the current aircraft documents and the instructor-approved sequence before trying again.","successMessage":"Correct - relate the answer to the booked aircraft and the conditions on the day."},{"id":"rpcconsol-q3","type":"single_choice","prompt":"Why is the self-debrief part of command readiness?","options":[{"id":"rpcconsol-q3-o1","label":"It shows the pilot can recognise evidence, risk and targeted improvement needs."},{"id":"rpcconsol-q3-o2","label":"It replaces instructor assessment."},{"id":"rpcconsol-q3-o3","label":"It guarantees a flight-test pass."},{"id":"rpcconsol-q3-o4","label":"It removes the need for records."}],"correctAnswer":"rpcconsol-q3-o1","required":true,"incorrectExplanation":"Review the lesson briefing, the current aircraft documents and the instructor-approved sequence before trying again.","successMessage":"Correct - relate the answer to the booked aircraft and the conditions on the day."},{"id":"rpcconsol-q4","type":"single_choice","prompt":"Before using a P92 speed, RPM, flap setting, limitation or emergency action, which source controls?","options":[{"id":"rpcconsol-q4-o1","label":"A figure remembered from another aircraft."},{"id":"rpcconsol-q4-o2","label":"An online forum post."},{"id":"rpcconsol-q4-o3","label":"The current Tecnam marketing page."},{"id":"rpcconsol-q4-o4","label":"The current flight manual, cockpit placard/checklist and instructor brief for the booked aircraft."}],"correctAnswer":"rpcconsol-q4-o4","required":true,"incorrectExplanation":"Review the lesson briefing, the current aircraft documents and the instructor-approved sequence before trying again.","successMessage":"Correct - relate the answer to the booked aircraft and the conditions on the day."}],"commonSources":[["NZ CAA Flight Instructor Guide briefing framework","https://www.aviation.govt.nz/licensing-and-certification/pilots/flight-training/flight-instructor-guide/briefings-introduction/"],["RAAus RPC syllabus","https://raaus.com.au/wp-content/uploads/2023/10/1-syllabus-of-flight-training-issue-7-v2-single-pages-1.pdf"],["RAAus Flight Operations Manual","https://raaus.com.au/wp-content/uploads/2024/07/RAAus-Flight-Operations-Manual.pdf"],["Tecnam P92 family overview - general information only","https://tecnam.com/aircraft/p92-echo-mkii/"]]},{"code":"RPC-REVIEW","title":"CFI Recommendation and Pilot Certificate Readiness Review","sources":[["RAAus syllabus","https://raaus.com.au/wp-content/uploads/2023/10/1-syllabus-of-flight-training-issue-7-v2-single-pages-1.pdf"],["RAAus Flight Operations Manual","https://raaus.com.au/wp-content/uploads/2024/07/RAAus-Flight-Operations-Manual.pdf"]],"outcomes":["Present complete training, exam, membership and aeronautical-experience evidence.","Explain RPC privileges, limitations and local operating responsibilities.","Agree on recommendation, targeted remediation or a documented hold point."],"p92":["Confirm the aircraft group and P92 type training recorded in the student file.","Demonstrate knowledge of the booked P92’s documents, limitations, loading and emergency references.","Distinguish club fleet procedures from regulatory privileges and aircraft limitations.","Bring uncertainties to the CFI; the review is a safety gate, not an administrative formality."],"sequence":["Audit training records, dual/PIC experience, solo authorisations and required exams.","Review membership, medical declaration, radio and identity evidence.","Discuss RPC privileges, passenger/cross-country limits and local procedures.","Review aircraft-specific knowledge and any remaining practical evidence.","Record recommendation, conditions, remedial work or reasons for deferral."],"threats":["Incomplete records mistaken for incomplete competence: reconcile evidence before deciding.","Minimum-hours fixation: competence and consistency remain required.","Pressure to recommend: the CFI must record a genuine readiness decision."],"readiness":["My logbook, exams and training record agree.","I can explain what an RPC does and does not authorise.","I can locate every current P92 limitation rather than relying on memory alone."],"questions":[{"prompt":"Does reaching the minimum flight time automatically establish RPC readiness?","correct":"No. Required experience, examinations and demonstrated competency must all be satisfied.","distractors":["Yes, regardless of competency.","Yes, if every flight used a P92.","Only the student decides."]},{"prompt":"What should happen if the logbook and CRM training record differ?","correct":"Reconcile and verify the evidence before recommendation.","distractors":["Use whichever total is higher.","Delete the older record.","Proceed and correct it after certificate issue."]},{"prompt":"Why must club procedures be distinguished from certificate privileges?","correct":"Both apply, but they come from different authorities and may impose different limits.","distractors":["Club procedures replace all regulations.","Certificate privileges replace aircraft limitations.","There is no difference."]}],"programIndex":17,"name":"RPC 17 - CFI Recommendation and Pilot Certificate Readiness Review","quiz":[{"id":"rpcreview-q1","type":"single_choice","prompt":"Does reaching the minimum flight time automatically establish RPC readiness?","options":[{"id":"rpcreview-q1-o1","label":"Yes, if every flight used a P92."},{"id":"rpcreview-q1-o2","label":"Only the student decides."},{"id":"rpcreview-q1-o3","label":"No. Required experience, examinations and demonstrated competency must all be satisfied."},{"id":"rpcreview-q1-o4","label":"Yes, regardless of competency."}],"correctAnswer":"rpcreview-q1-o3","required":true,"incorrectExplanation":"Review the lesson briefing, the current aircraft documents and the instructor-approved sequence before trying again.","successMessage":"Correct - relate the answer to the booked aircraft and the conditions on the day."},{"id":"rpcreview-q2","type":"single_choice","prompt":"What should happen if the logbook and CRM training record differ?","options":[{"id":"rpcreview-q2-o1","label":"Proceed and correct it after certificate issue."},{"id":"rpcreview-q2-o2","label":"Reconcile and verify the evidence before recommendation."},{"id":"rpcreview-q2-o3","label":"Use whichever total is higher."},{"id":"rpcreview-q2-o4","label":"Delete the older record."}],"correctAnswer":"rpcreview-q2-o2","required":true,"incorrectExplanation":"Review the lesson briefing, the current aircraft documents and the instructor-approved sequence before trying again.","successMessage":"Correct - relate the answer to the booked aircraft and the conditions on the day."},{"id":"rpcreview-q3","type":"single_choice","prompt":"Why must club procedures be distinguished from certificate privileges?","options":[{"id":"rpcreview-q3-o1","label":"Both apply, but they come from different authorities and may impose different limits."},{"id":"rpcreview-q3-o2","label":"Club procedures replace all regulations."},{"id":"rpcreview-q3-o3","label":"Certificate privileges replace aircraft limitations."},{"id":"rpcreview-q3-o4","label":"There is no difference."}],"correctAnswer":"rpcreview-q3-o1","required":true,"incorrectExplanation":"Review the lesson briefing, the current aircraft documents and the instructor-approved sequence before trying again.","successMessage":"Correct - relate the answer to the booked aircraft and the conditions on the day."},{"id":"rpcreview-q4","type":"single_choice","prompt":"Before using a P92 speed, RPM, flap setting, limitation or emergency action, which source controls?","options":[{"id":"rpcreview-q4-o1","label":"A figure remembered from another aircraft."},{"id":"rpcreview-q4-o2","label":"An online forum post."},{"id":"rpcreview-q4-o3","label":"The current Tecnam marketing page."},{"id":"rpcreview-q4-o4","label":"The current flight manual, cockpit placard/checklist and instructor brief for the booked aircraft."}],"correctAnswer":"rpcreview-q4-o4","required":true,"incorrectExplanation":"Review the lesson briefing, the current aircraft documents and the instructor-approved sequence before trying again.","successMessage":"Correct - relate the answer to the booked aircraft and the conditions on the day."}],"commonSources":[["NZ CAA Flight Instructor Guide briefing framework","https://www.aviation.govt.nz/licensing-and-certification/pilots/flight-training/flight-instructor-guide/briefings-introduction/"],["RAAus RPC syllabus","https://raaus.com.au/wp-content/uploads/2023/10/1-syllabus-of-flight-training-issue-7-v2-single-pages-1.pdf"],["RAAus Flight Operations Manual","https://raaus.com.au/wp-content/uploads/2024/07/RAAus-Flight-Operations-Manual.pdf"],["Tecnam P92 family overview - general information only","https://tecnam.com/aircraft/p92-echo-mkii/"]]},{"code":"RPC-FLT-TEST","title":"Pilot Certificate Flight Test","sources":[["RAAus syllabus","https://raaus.com.au/wp-content/uploads/2023/10/1-syllabus-of-flight-training-issue-7-v2-single-pages-1.pdf"],["RAAus Flight Operations Manual","https://raaus.com.au/wp-content/uploads/2024/07/RAAus-Flight-Operations-Manual.pdf"]],"outcomes":["Arrive with the eligibility, records and aircraft preparation required for the RPC flight test.","Demonstrate Pilot Certificate command standard across the examiner-selected profile.","Understand the result, limitations, record completion and next actions."],"p92":["Prepare the actual test aircraft’s status, documents, loading, fuel, performance and limitations.","Use normal BFC P92 procedures; do not invent “test technique” that differs from trained safe practice.","Correct small deviations early and state decisions when operational judgement is being exercised.","If safety requires examiner intervention or a go-around, respond immediately and professionally."],"sequence":["Present membership, identity, exams, logbook, training and recommendation evidence.","Complete planning and explain aircraft, weather, airspace and operational decisions.","Conduct the examiner-selected ground and flight profile.","Secure the aircraft and participate in the result and evidence debrief.","Complete required records and clarify privileges, limitations or retraining."],"threats":["Performance anxiety: use normal flows, prioritise safety and ask for clarification when appropriate.","Perceived pressure to continue: a go-around or conservative decision can demonstrate command judgement.","Post-result misunderstanding: repeat back limitations and next administrative steps."],"readiness":["I have every required document and can explain the plan without instructor prompts.","I will fly the aircraft I have been trained to fly, not a memorised script.","I understand that only the authorised examiner and RAAus process determine the official result."],"questions":[{"prompt":"What is the best technique for the RPC flight test?","correct":"Use the same disciplined P92 procedures and command judgement used in training.","distractors":["Adopt unpractised manoeuvre techniques to impress the examiner.","Memorise a fixed profile and ignore changed conditions.","Avoid making conservative decisions."]},{"prompt":"Can a go-around be appropriate during a flight test?","correct":"Yes. A timely go-around can demonstrate sound command judgement.","distractors":["No. Every approach must end in a landing.","Only if the radio fails.","Only after touchdown."]},{"prompt":"Who determines the official RPC flight-test result and certificate processing?","correct":"The authorised examiner records the result and RAAus completes the applicable process.","distractors":["The online quiz.","The aircraft owner.","Any instructor who observes the landing."]}],"programIndex":18,"name":"RPC 18 - Pilot Certificate Flight Test","quiz":[{"id":"rpcflttest-q1","type":"single_choice","prompt":"What is the best technique for the RPC flight test?","options":[{"id":"rpcflttest-q1-o1","label":"Use the same disciplined P92 procedures and command judgement used in training."},{"id":"rpcflttest-q1-o2","label":"Adopt unpractised manoeuvre techniques to impress the examiner."},{"id":"rpcflttest-q1-o3","label":"Memorise a fixed profile and ignore changed conditions."},{"id":"rpcflttest-q1-o4","label":"Avoid making conservative decisions."}],"correctAnswer":"rpcflttest-q1-o1","required":true,"incorrectExplanation":"Review the lesson briefing, the current aircraft documents and the instructor-approved sequence before trying again.","successMessage":"Correct - relate the answer to the booked aircraft and the conditions on the day."},{"id":"rpcflttest-q2","type":"single_choice","prompt":"Can a go-around be appropriate during a flight test?","options":[{"id":"rpcflttest-q2-o1","label":"No. Every approach must end in a landing."},{"id":"rpcflttest-q2-o2","label":"Only if the radio fails."},{"id":"rpcflttest-q2-o3","label":"Only after touchdown."},{"id":"rpcflttest-q2-o4","label":"Yes. A timely go-around can demonstrate sound command judgement."}],"correctAnswer":"rpcflttest-q2-o4","required":true,"incorrectExplanation":"Review the lesson briefing, the current aircraft documents and the instructor-approved sequence before trying again.","successMessage":"Correct - relate the answer to the booked aircraft and the conditions on the day."},{"id":"rpcflttest-q3","type":"single_choice","prompt":"Who determines the official RPC flight-test result and certificate processing?","options":[{"id":"rpcflttest-q3-o1","label":"The aircraft owner."},{"id":"rpcflttest-q3-o2","label":"Any instructor who observes the landing."},{"id":"rpcflttest-q3-o3","label":"The authorised examiner records the result and RAAus completes the applicable process."},{"id":"rpcflttest-q3-o4","label":"The online quiz."}],"correctAnswer":"rpcflttest-q3-o3","required":true,"incorrectExplanation":"Review the lesson briefing, the current aircraft documents and the instructor-approved sequence before trying again.","successMessage":"Correct - relate the answer to the booked aircraft and the conditions on the day."},{"id":"rpcflttest-q4","type":"single_choice","prompt":"Before using a P92 speed, RPM, flap setting, limitation or emergency action, which source controls?","options":[{"id":"rpcflttest-q4-o1","label":"The current Tecnam marketing page."},{"id":"rpcflttest-q4-o2","label":"The current flight manual, cockpit placard/checklist and instructor brief for the booked aircraft."},{"id":"rpcflttest-q4-o3","label":"A figure remembered from another aircraft."},{"id":"rpcflttest-q4-o4","label":"An online forum post."}],"correctAnswer":"rpcflttest-q4-o2","required":true,"incorrectExplanation":"Review the lesson briefing, the current aircraft documents and the instructor-approved sequence before trying again.","successMessage":"Correct - relate the answer to the booked aircraft and the conditions on the day."}],"commonSources":[["NZ CAA Flight Instructor Guide briefing framework","https://www.aviation.govt.nz/licensing-and-certification/pilots/flight-training/flight-instructor-guide/briefings-introduction/"],["RAAus RPC syllabus","https://raaus.com.au/wp-content/uploads/2023/10/1-syllabus-of-flight-training-issue-7-v2-single-pages-1.pdf"],["RAAus Flight Operations Manual","https://raaus.com.au/wp-content/uploads/2024/07/RAAus-Flight-Operations-Manual.pdf"],["Tecnam P92 family overview - general information only","https://tecnam.com/aircraft/p92-echo-mkii/"]]}]$rpc$::jsonb)
  loop
    select id into v_lesson_id
    from public.training_lessons
    where course_id = v_course_id
      and sequence_code = v_item ->> 'code';
    if v_lesson_id is null then
      raise exception 'RPC lesson % was not found', v_item ->> 'code';
    end if;

    v_program_id := public.learning_seed_uuid('bfc-rpc-p92-program:' || (v_item ->> 'code'));
    v_prepare_section_id := public.learning_seed_uuid('bfc-rpc-p92-prepare:' || (v_item ->> 'code'));
    v_apply_section_id := public.learning_seed_uuid('bfc-rpc-p92-apply:' || (v_item ->> 'code'));
    v_check_section_id := public.learning_seed_uuid('bfc-rpc-p92-check:' || (v_item ->> 'code'));

    insert into public.learning_programs(
      id, name, category, description, cover_photo_url, status,
      schedule_type, self_paced_limit_type, price_type, price_cents,
      visibility, step_order_mode, future_steps_visible,
      video_watch_required, auto_enrol_from_lesson_links,
      source_metadata, published_at, updated_at
    ) values (
      v_program_id,
      v_item ->> 'name',
      'RAAus RPC - Tecnam P92',
      'Online preparation for ' || (v_item ->> 'title') ||
        '. Complete this before the linked flight lesson. Training aid only: the current aircraft flight manual, cockpit placards/checklist, BFC procedures and instructor directions take precedence.',
      '/aircraft-icons/tecnam.png',
      'published',
      'self_paced',
      'none',
      'free',
      0,
      'secret',
      'in_order',
      true,
      false,
      true,
      jsonb_build_object(
        'contentVersion', '2026.07',
        'reviewedAt', '2026-07-29',
        'aircraftFamily', 'Tecnam P92 Echo Super',
        'jurisdiction', 'Australia - RAAus',
        'sourceFramework', 'New Zealand CAA Flight Instructor Guide revised 2023',
        'authoritativeFigures', 'Current aircraft flight manual, cockpit placards/checklist and BFC procedures'
      ),
      now(),
      now()
    )
    on conflict (id) do update
    set name = excluded.name,
        category = excluded.category,
        description = excluded.description,
        cover_photo_url = excluded.cover_photo_url,
        status = excluded.status,
        visibility = excluded.visibility,
        step_order_mode = excluded.step_order_mode,
        future_steps_visible = excluded.future_steps_visible,
        auto_enrol_from_lesson_links = excluded.auto_enrol_from_lesson_links,
        source_metadata = excluded.source_metadata,
        updated_at = now();

    delete from public.learning_program_sections where program_id = v_program_id;

    insert into public.learning_program_sections(id, program_id, title, description, sort_order)
    values
      (v_prepare_section_id, v_program_id, 'Prepare', 'Understand the lesson and the aircraft-specific considerations before flight.', 0),
      (v_apply_section_id, v_program_id, 'Apply', 'Chair-fly the sequence and identify threats, controls and decision points.', 1),
      (v_check_section_id, v_program_id, 'Check', 'Demonstrate preparation before the flight lesson.', 2);

    v_sources := coalesce(v_item -> 'sources', '[]'::jsonb) ||
      coalesce(v_item -> 'commonSources', '[]'::jsonb);
    v_blocks := jsonb_build_array(
      jsonb_build_object(
        'id', 'outcomes',
        'type', 'rich_text',
        'title', 'Observable lesson outcomes',
        'text', (select string_agg('• ' || value, E'\n') from jsonb_array_elements_text(v_item -> 'outcomes'))
      ),
      jsonb_build_object(
        'id', 'authority',
        'type', 'rich_text',
        'title', 'Authority and aircraft rule',
        'text', 'This program adapts an instructor-training framework to the BFC RAAus course. It is not an operating checklist and does not authorise solo flight or a manoeuvre. Use the current documents and instructor brief for the exact P92 registration booked.'
      )
    );
    v_sort := 0;
    for v_source in select value from jsonb_array_elements(v_sources)
    loop
      v_blocks := v_blocks || jsonb_build_array(jsonb_build_object(
        'id', 'source-' || v_sort,
        'type', 'button',
        'title', v_source ->> 0,
        'label', 'Open official reference',
        'url', v_source ->> 1
      ));
      v_sort := v_sort + 1;
    end loop;

    insert into public.learning_program_steps(
      id, program_id, section_id, step_type, title, description,
      content_blocks, quiz_questions, passing_score_percent,
      sort_order, is_required
    ) values (
      public.learning_seed_uuid('bfc-rpc-p92-outcomes:' || (v_item ->> 'code')),
      v_program_id,
      v_prepare_section_id,
      'article',
      'Lesson outcomes and official references',
      'Know what you should be able to demonstrate and which documents control.',
      v_blocks,
      '[]'::jsonb,
      null,
      0,
      true
    );

    insert into public.learning_program_steps(
      id, program_id, section_id, step_type, title, description,
      content_blocks, quiz_questions, passing_score_percent,
      sort_order, is_required
    ) values (
      public.learning_seed_uuid('bfc-rpc-p92-aircraft:' || (v_item ->> 'code')),
      v_program_id,
      v_prepare_section_id,
      'article',
      'Tecnam P92 Echo Super application',
      'Relate the lesson to the BFC P92 fleet without substituting generic figures for the booked aircraft.',
      jsonb_build_array(
        jsonb_build_object(
          'id', 'p92-focus',
          'type', 'rich_text',
          'title', 'P92 focus',
          'text', (select string_agg('• ' || value, E'\n') from jsonb_array_elements_text(v_item -> 'p92'))
        ),
        jsonb_build_object(
          'id', 'booked-aircraft',
          'type', 'button',
          'title', 'BFC aircraft documents',
          'label', 'Open the aircraft list and select the booked P92',
          'url', '/aircraft'
        )
      ),
      '[]'::jsonb,
      null,
      1,
      true
    );

    insert into public.learning_program_steps(
      id, program_id, section_id, step_type, title, description,
      content_blocks, quiz_questions, passing_score_percent,
      sort_order, is_required
    ) values (
      public.learning_seed_uuid('bfc-rpc-p92-chairfly:' || (v_item ->> 'code')),
      v_program_id,
      v_apply_section_id,
      'article',
      'Chair-fly the lesson',
      'Rehearse the sequence, verbal calls, threats and readiness gates before entering the aircraft.',
      jsonb_build_array(
        jsonb_build_object(
          'id', 'sequence',
          'type', 'rich_text',
          'title', 'Instructor-approved sequence',
          'text', (select string_agg((ordinality::text || '. ' || value), E'\n') from jsonb_array_elements_text(v_item -> 'sequence') with ordinality)
        ),
        jsonb_build_object(
          'id', 'threats',
          'type', 'rich_text',
          'title', 'Threat and error management',
          'text', (select string_agg('• ' || value, E'\n') from jsonb_array_elements_text(v_item -> 'threats'))
        ),
        jsonb_build_object(
          'id', 'readiness',
          'type', 'rich_text',
          'title', 'Ready for the instructor brief when...',
          'text', (select string_agg('□ ' || value, E'\n') from jsonb_array_elements_text(v_item -> 'readiness'))
        )
      ),
      '[]'::jsonb,
      null,
      2,
      true
    );

    insert into public.learning_program_steps(
      id, program_id, section_id, step_type, title, description,
      content_blocks, quiz_questions, passing_score_percent,
      sort_order, is_required
    ) values (
      public.learning_seed_uuid('bfc-rpc-p92-quiz:' || (v_item ->> 'code')),
      v_program_id,
      v_check_section_id,
      'quiz',
      'Knowledge check',
      'Answer every question. A score of at least 80% is required; review the briefing before another attempt.',
      '[]'::jsonb,
      v_item -> 'quiz',
      80,
      3,
      true
    );

    insert into public.learning_program_lesson_links(
      program_id, training_course_id, training_lesson_id, visibility_timing
    ) values (
      v_program_id, v_course_id, v_lesson_id, 'at_or_before_lesson'
    )
    on conflict (program_id, training_course_id, training_lesson_id) do update
    set visibility_timing = excluded.visibility_timing;
  end loop;
end;
$seed$;

drop function public.learning_seed_uuid(text);
